head.script:
/***************************************************************************************
* 시스템명 : 산재보상시스템
* 업무명   : 결재함관리
* 파일명   : as-is : QB0306.xml
* 파일명   : to-be : CM0201100M.xml
* 작성자   : 오재광
* 작성일   : 2025.01.09
*
* 설 명 : 결재 진행 상태(결재, 접수, 결재중, 반려, 보류, 완결) 별 관리 화면
*---------------------------------------------------------------------------------------
* 변경일	     변경자		 변경내역
*---------------------------------------------------------------------------------------
* 2025.01.09     오재광		최초 프로그램 작성
*
*---------------------------------------------------------------------------------------
****************************************************************************************/


/****************************************************************************************/
/* 01. Form 변수정의									                                */
/****************************************************************************************/

//다중 페이지 처리를 위한 전역변수
var gv_paging_totalRows_Gyeoljaeham		= "";
var gv_paging_totalRows_Jeopsuham 		= "";
var gv_paging_totalRows_Gyeoljaejung 	= "";
var gv_paging_totalRows_Banryeoham 		= "";
var gv_paging_totalRows_Boryuham 		= "";
var gv_paging_totalRows_Wangyeolham 	= "";

//필터 적용한 뒤 다시 페이징 조회시, 필터처리 중복조회 문제 해결을 위하여...1 전역변수 (목록펼치기 : 0 / 목록접기: 1)
scwin.fv_GyeoljaehamFilter 	= 0;
scwin.fv_JeopsuhamFilter 	= 0;
scwin.fv_GyeoljaejungFilter = 0;
scwin.fv_BanryeohamFilter 	= 0;
scwin.fv_BoryuhamFilter 	= 0;
scwin.fv_WangyeolhamFilter 	= 0;

//페이징 조회 시 속도문제로 그리드가 한번에 보이지 않아 Redraw = false 적용시 발생하는 문제해결을 위한 전역변수
scwin.fv_GyeoljaehamJohoeCnt 	= "";
scwin.fv_JeopsuhamJohoeCnt 		= "";
scwin.fv_GyeoljaejungJohoeCnt 	= "";
scwin.fv_BanryeohamJohoeCnt 	= "";
scwin.fv_BoryuhamJohoeCnt 		= "";
scwin.fv_WangyeolhamJohoeCnt 	= "";

//결재처리 후 총 건수 재출력을 위한 전역변수
scwin.fv_GyeoljaehamAftGyeoljaeCnt 	= "";
scwin.fv_JeopsuhamAftGyeoljaeCnt 	= "";
scwin.fv_GyeoljaejungAftGyeoljaeCnt = "";
scwin.fv_BoryuhamAftGyeoljaeCnt 	= "";
scwin.fv_BanryeohamAftGyeoljaeCnt 	= "";

//담당자ID, 담당자명, 선택사항값
scwin.oldTabIdx = -1;
scwin.fv_Damdangja_Id = "";
scwin.fv_Damdangja_Nm = "";
scwin.fv_Dwmdangja_Fg = "";

//Redraw시 그리드 내의 포커스 이동을 막기 위한 전역변수
var v_GyeoljaehamFocus 	= "";
var v_JeopsuhamFocus 	= "";
var v_GyeoljaejungFocus = "";
var v_BanryeohamFocus 	= "";
var v_BoryuhamFocus 	= "";

scwin.fv_GijunJeopsuNo  = "";

// 포탈에서 연계 처리 전역변수
scwin.fv_YeonGeyYn	= "";   // 포털 연계여부
scwin.fv_TabNo		= "";	// 결재함탭 파라미터
scwin.fv_MinwonFg	= "";	// 민원구분 파라미터

//접수함목록 총 건수 전역변수
scwin.fv_JeopsuhamMokrokTotCnt = "";

scwin.fv_LogOn = true;

/* 결재함 분할처리 관련 변수*/
scwin.fv_GyeoljaeBunhalFg = false;	//분할처리구분
scwin.fv_LimitCnt = 0;	//분활처리할 건수
scwin.fv_LoopCnt = 0;	//분할건수
scwin.fv_pDsObj = null;	//분할처리할 데이터셋
scwin.fv_dsObj = null;	//분할 처리된 데이터셋
scwin.fv_PDsRowCnt = 0;	//처리할건수
scwin.fv_GyeoljaehamTotCnt = 0;	//결재함목록건수
scwin.fv_ResultCheoriCnt = 0;	//분할처리후 처리결과건수
scwin.fv_BunhalCheoriInx = 0;	//처리인덱스
scwin.fv_StartInx = 0;	//서브 루프 시작 인덱스
scwin.fv_EndInx = 0;	//서브 루프 끝 인덱스
scwin.fv_ResultTextCom = null;
scwin.fv_CheoriDsObj = null;

scwin.fv_JehanCnt = 50; 	// 일괄결재 제한 건수
scwin.fv_JehanTmYn = "";
scwin.fv_JehanMsg = "";

scwin.fv_MinwonDocCd = "";	// 민원서류 3327일 경우 예외처리
scwin.fv_failCnt = 0;



scwin.gwYnImageInfo = {
	inputType : "textImage"
	, options : {
		imageSrc : "/cm/images/base/btn_grid_w.bmp"
		, viewType: "icon"
	}
}
scwin.cheombufileYnImageInfo = {
	inputType : "textImage"
	, options : {
		imageSrc : "/cm/images/base/icon_grid_file.bmp"
		, imageStyle : "width: 10px;"
		, viewType: "icon"
		, blockSelect: false
	}
}



/*******************************************************************************
* FUNCTION 명 : scwin.onpageload
* FUNCTION 기능설명 : 컴포넌트 초기화
*******************************************************************************/
scwin.onpageload = function() {

	chk_totalJadongIpsuYn.visible(false);

   	if (com.gfn_CallByPortal()) {
		scwin.fv_YeonGeyYn="Y";
   	} else {
		scwin.fv_YeonGeyYn="N";
	}

	scwin.fv_TabNo = com.gfn_GetExtParam("v_TabNo");
	scwin.fv_MinwonFg = com.gfn_GetExtParam("v_MinwonFg");

	cob_GyeoljaehamJohoeJogeon_minwonFg.bind("onkeydown", function(e) {
		if (!e.shiftKey && !e.ctrlKey && !e.altKey) {
			if (e.keyCode == "13") {
				if (tab1.getSelectedTabIndex() == 0) {
					cob_GyeoljaehamJohoeJogeon_userFg.focus();
				} else {
					edt_GyeoljaehamJohoeJogeon_cheoriDt.focus();
				}
			}
		}
	});

	cob_GyeoljaehamJohoeJogeon_userFg.bind("onkeydown", function(e) {
		if (!e.shiftKey && !e.ctrlKey && !e.altKey) {
			if (e.keyCode == "13") {
				edt_GyeoljaehamJohoeJogeon_cheoriDt.focus();
			}
		}
	});

	scwin.fn_Init();
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_Init
* FUNCTION 기능설명 : 화면 초기화
*******************************************************************************/
scwin.fn_Init = async function() {
	scwin.fn_InitAllDataSet();
    scwin.fn_InitComboBoxForCommonCode();

    //화면 Open시 결재비밀번호변경여부조회 서버이벤트를 호출
    await scwin.fn_RetrieveGyeoljaePwChangeYn();

    //포탈에서 연계되었는지 확인
	if (scwin.fv_YeonGeyYn=="Y") {
		//포탈 연계 시 From 처리일자는 현재일자 셋팅
		edt_GyeoljaehamJohoeJogeon_cheoriDt1.setValue(com.gfn_GetDate().substr(0, 8));
		edt_GyeoljaehamJohoeJogeon_cheoriDt.setValue(com.addDate(com.gfn_GetDate().substr(0, 8), -20));

		if (com.trim(scwin.fv_MinwonFg) != "") {
			dma_GyeoljaehamJohoeJogeon.set("MINWON_FG", scwin.fv_MinwonFg);
			tab1.setSelectedTabIndex(com.toNumber(scwin.fv_TabNo));
		} else if (com.gfn_IsNull(com.gfn_SsMinwonJeopsuFg())) {
			cob_GyeoljaehamJohoeJogeon_minwonFg.setValue(2);
		} else {
			cob_GyeoljaehamJohoeJogeon_minwonFg.setValue(com.gfn_SsMinwonJeopsuFg());
		}

    } else {

		//사용자의 부서코드가 감사실 또는 감사부이면 민원구분을 감사로 셋팅하고
		//감사부 또는 감사실이 아니면 세션에서 가져온 민원접수구분으로 민원구분 콤보박스를 셋팅
		if (com.gfn_SsBuseoCd() == "600" || com.gfn_SsBuseoCd() == "601") {
			cob_GyeoljaehamJohoeJogeon_minwonFg.setValue(8);
		} else {
			if (com.gfn_IsNull(com.gfn_SsMinwonJeopsuFg())) {
				cob_GyeoljaehamJohoeJogeon_minwonFg.setValue(2);
			} else {
				cob_GyeoljaehamJohoeJogeon_minwonFg.setValue(com.gfn_SsMinwonJeopsuFg());
			}
		}
		//From 처리일자는 현재-20, To 처리일자를 현재로 셋팅
		edt_GyeoljaehamJohoeJogeon_cheoriDt1.setValue(com.gfn_GetDate().substr(0, 8));
		edt_GyeoljaehamJohoeJogeon_cheoriDt.setValue(com.addDate(com.gfn_GetDate().substr(0, 8), -20));
    }
    //세션에서 사용자 지사코드와 지사명을 가져와 세팅
    edt_GyeoljaehamJohoeJogeon_gwanriJisa.setValue(com.gfn_SsJisaCd());
    edt_GyeoljaehamJohoeJogeon_gwanriJisa2.setValue(com.gfn_SsJisaName());

    //번호구분 기본값 '선택' & 선택사항 기본값 세팅
    cob_GyeoljaehamJohoeJogeon_noFg.setValue("");

    //결재함탭일 때에만 선택사항 보이게 하기
    if (tab1.getSelectedTabIndex() == 0) {
		st_GyeoljaehamJohoeJogeon_userFg.visible(true);
		div2.visible(true);
    } else {
		st_GyeoljaehamJohoeJogeon_userFg.visible(false);
		div2.visible(false);
    }

	cob_GyeoljaehamJohoeJogeon_userFg.setSelectedIndex(0);
	cob_GyeoljaehamJohoeJogeon_minwonFg.focus();

	scwin.fn_GetUserEopmuMokrok();

	scwin.fv_GijunJeopsuNo = com.gfn_SsJisaCd() + com.gfn_GetDate().substr(0, 4);
	mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.setValue(scwin.fv_GijunJeopsuNo);
	mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.setValue(scwin.fv_GijunJeopsuNo);

	cob_GyeoljaehamJohoeJogeon_minwonFg.focus();
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_InitAllDataSet
* FUNCTION 기능설명 : 모든 DataCollection 을 초기화
*******************************************************************************/
scwin.fn_InitAllDataSet = function() {
	//결재함조회조건 DataSet
	dma_GyeoljaehamJohoeJogeon.setEmptyValue();
	dma_GyeoljaehamJohoeJogeon.reform();

	//일괄체크 DataSet
	dma_IlgwalCheck.setEmptyValue();
	dma_IlgwalCheck.reform();

	//ds_MokrokInfo DataSet
	dlt_MokrokInfo.removeAll();

	//ds_ResultInfo DataSet
	dma_ResultInfo.setEmptyValue();
	dma_ResultInfo.reform();

	//ds_GyeoljaeResultInfo DataSet
	dma_GyeoljaeResultInfo.setEmptyValue();
	dma_GyeoljaeResultInfo.reform();

	//결재함목록 DataSet
	dlt_GyeoljaehamMokrok.removeAll();

	//접수함목록 DataSet
	dlt_JeopsuhamMokrok.removeAll();

	//결재중목록 DataSet
	dlt_GyeoljaejungMokrok.removeAll();

	//반려함목록 DataSet
	dlt_BanryeohamMokrok.removeAll();

	//보류함목록 DataSet
	dlt_BoryuhamMokrok.removeAll();

	//완결함목록 DataSet
	dlt_WangyeolhamMokrok.removeAll();

	//대결할자체크 inDS DataSet
	dma_UserInfo.setEmptyValue();
	dma_UserInfo.reform();

	//결재암호처리 outDs DataSet
	dma_GyeoljaeInfo.setEmptyValue();
	dma_GyeoljaeInfo.reform();
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_InitComboBoxForCommonCode
* FUNCTION 기능설명 : Global 공통코드 조회
*******************************************************************************/
scwin.fn_InitComboBoxForCommonCode = function() {
	//민원구분 코드
	var codeOptions = [
        {code: "Q0001", compID: "cob_GyeoljaehamJohoeJogeon_minwonFg", dataNm: "dlt_MinwonFg"}
    ];
    com.setCommonCode(codeOptions, scwin.fn_CommonCodeCallback);
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_CommonCodeCallback
* FUNCTION 기능설명 : Global 공통코드 조회 결과 Callback
*******************************************************************************/
scwin.fn_CommonCodeCallback = function () {
	dlt_MinwonFg.setCellData(com.gfn_searchRow(dlt_MinwonFg, "GT_CD=='2'"), "GT_CD_NM1", "재활보상");

	com.dataListFilter("dlt_MinwonFg", "GT_CD != '9' && GT_CD != '1' && GT_CD != '3'");
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_RetrieveGyeoljaePwChangeYn
* FUNCTION 기능설명 : 결재비밀번호변경여부조회
*******************************************************************************/
scwin.fn_RetrieveGyeoljaePwChangeYn = async function() {
	var srvId		 = "RetrieveGyeoljaePwChangeIlsuCmd";
	var strURL		 = "/cm/cm02/0101/CM0201100M_E001.do";
	var strinDsList	 = "";
	var stroutDsList = "['dma_GyeoljaeResultInfo']";
	var strArgument	 = "";

	await com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, scwin.fn_CallBack, false, true, true);
};



/*******************************************************************************
* FUNCTION 명 : scwin.btn_GyeoljaehamJohoeJogeon_SelectJisaCdPup_onclick
* FUNCTION 기능설명 : 지사코드선택 (onclick)
*******************************************************************************/
scwin.btn_GyeoljaehamJohoeJogeon_SelectJisaCdPup_onclick = function(e) {
    scwin.fn_SelectJisaCd("click");
};



/*******************************************************************************
* FUNCTION 명 : scwin.edt_GyeoljaehamJohoeJogeon_gwanriJisa_onkeydown
* FUNCTION 기능설명 : 지사코드선택 (onkeydown)
*******************************************************************************/
scwin.edt_GyeoljaehamJohoeJogeon_gwanriJisa_onkeydown = function(e) {
    // Shift, Control, Alt 키가 눌려져 있지 않은 경우만 단축키 실행.
	if (!e.shiftKey && !e.ctrlKey && !e.altKey) {
		if (e.keyCode == "13") {
			// keyDown이벤트가 change이벤트보다 먼저발생하기때문에 강제 설정해준다.
			scwin.fn_SelectJisaCd("KeyDown");
		}
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_SelectJisaCd
* FUNCTION 기능설명 : 지사코드정보를 가져올 수 있는 화면을 Open 하고 지사코드로 조회한 지사코드정보 목록을 읽어온다.
*******************************************************************************/
scwin.fn_SelectJisaCd = async function(flag) {
	var v_Param = "";
    var v_Flag = flag;
		v_Param += "v_JisaCd=" + edt_GyeoljaehamJohoeJogeon_gwanriJisa.getValue();

	var vRtnInfo = new Array();
		vRtnInfo = await com.gfn_GetJisaInfo(v_Flag, v_Param);

	if (!com.gfn_IsNull(vRtnInfo[0])) {
		edt_GyeoljaehamJohoeJogeon_gwanriJisa.setValue(vRtnInfo[0]);
		edt_GyeoljaehamJohoeJogeon_gwanriJisa2.setValue(vRtnInfo[1]);
		edt_GyeoljaehamJohoeJogeon_minwonDoc.focus();
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.edt_GyeoljaehamJohoeJogeon_gwanriJisa_onchange
* FUNCTION 기능설명 : 관리지사 (onchange)
*******************************************************************************/
scwin.edt_GyeoljaehamJohoeJogeon_gwanriJisa_onchange = function(info) {
	edt_GyeoljaehamJohoeJogeon_gwanriJisa2.setValue("");
};



/*******************************************************************************
* FUNCTION 명 : scwin.btn_GyeoljaehamJohoeJogeon_SelectUserPup_onclick
* FUNCTION 기능설명 : 선택사항 - 사용자선택 (onclick)
*******************************************************************************/
scwin.btn_GyeoljaehamJohoeJogeon_SelectUserPup_onclick = function(e) {
    scwin.fn_SelectUserInfo("click");
};



/*******************************************************************************
* FUNCTION 명 : scwin.edt_GyeoljaehamJohoeJogeon_userFg1_onkeydown
* FUNCTION 기능설명 : 선택사항 - 사용자선택 (onkeydown)
*******************************************************************************/
scwin.edt_GyeoljaehamJohoeJogeon_userFg1_onkeydown = function(e) {
    // Shift, Control, Alt 키가 눌려져 있지 않은 경우만 단축키 실행.
	if (!e.shiftKey && !e.ctrlKey && !e.altKey) {
		if (e.keyCode == "13") {
			// keyDown이벤트가 change이벤트보다 먼저발생하기때문에 강제 설정해준다.
			scwin.fn_SelectUserInfo("keyDown");
		}
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_SelectUserInfo
* FUNCTION 기능설명 : 사용자코드를 가져올 수 있는 화면을 Open하고 선택된 사용자정보를 읽어온다.
*******************************************************************************/
scwin.fn_SelectUserInfo = async function(flag) {
    var v_Flag = flag;
    var v_Param = "v_UserId=" + edt_GyeoljaehamJohoeJogeon_userFg1.getValue();
	var v_UserInfo = new Array();
		v_UserInfo = await com.gfn_GetUserInfo(v_Flag, v_Param);

	if (!com.gfn_IsNull(v_UserInfo[0])) {
		edt_GyeoljaehamJohoeJogeon_userFg1.setValue(v_UserInfo[0]);
		edt_GyeoljaehamJohoeJogeon_userFg3.setValue(v_UserInfo[1]);
		edt_GyeoljaehamJohoeJogeon_cheoriDt.focus();
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.edt_GyeoljaehamJohoeJogeon_userFg1_onchange = function(info)
* FUNCTION 기능설명 : 선택사항 - 사용자선택 (onchange)
*******************************************************************************/
scwin.edt_GyeoljaehamJohoeJogeon_userFg1_onchange = function(info) {
	edt_GyeoljaehamJohoeJogeon_userFg3.setValue("");
};



/*******************************************************************************
* FUNCTION 명 : scwin.btn_GyeoljaehamJohoeJogeon_SelectGyeoljaejaPup_onclick = function(info)
* FUNCTION 기능설명 : 결재자선택
 *		            -.세션정보의 로그인한 사용자ID, 지사코드, 결재직급에 따른 하위결재자를 선택할 수 있는 화면을 Open하고 선택된 사용자정보를 읽어온다.
 *	            	-.결재직급이 3급이하만 가능하다.
*******************************************************************************/
scwin.btn_GyeoljaehamJohoeJogeon_SelectGyeoljaejaPup_onclick = async function(e) {

    if(com.toInteger(com.gfn_SsUserJikgeupCd()) <= 3) {
		var param = "fv_JISA_CD=" + com.quote(com.gfn_SsJisaCd());
			param += " fv_USER_ID=" + com.quote(edt_GyeoljaehamJohoeJogeon_userFg1.getValue());
			param += " fv_GYEOLJAE_JIKGEUP_CD=" + com.quote(dma_GyeoljaeResultInfo.get("GYEOLJAE_JIKGEUP_CD"));

		var v_RetStr = new Array();
			v_RetStr = await com.gfn_Dialog("/ui/sia/biz/cm/cm02/0101/CM0201110P.xml", param, 360, 360, "결재자 조회");
		if (!com.gfn_IsNull(v_RetStr[0])) {
			edt_GyeoljaehamJohoeJogeon_userFg1.setValue(v_RetStr[0]);
			edt_GyeoljaehamJohoeJogeon_userFg3.setValue(v_RetStr[1]);
			edt_GyeoljaehamJohoeJogeon_cheoriDt.focus();
		}
    }

};



/*******************************************************************************
