/*******************************************************************************
* FUNCTION 명 : scwin.fn_retrieveMinwonInfo
* FUNCTION 기능설명 : 민원서류코드,민원서류명을 조회한다.
*******************************************************************************/
scwin.fn_retrieveMinwonInfo = async function(v_Flag) {
	var v_Param = "v_Minwon_Cd=" + com.trim(edt_GyeoljaehamJohoeJogeon_minwonDoc.getValue());
		v_Param += " v_Minwon_Fg=" + cob_GyeoljaehamJohoeJogeon_minwonFg.getValue();
	var v_MinwonInfo = new Array();
		v_MinwonInfo = await com.cfn_GetMinwonDocInfo(v_Flag, v_Param);

	if (!com.gfn_IsNull(v_MinwonInfo)) {
		edt_GyeoljaehamJohoeJogeon_minwonDoc.setValue(v_MinwonInfo[0]);
		edt_GyeoljaehamJohoeJogeon_minwonDoc2.setValue(v_MinwonInfo[1]);
		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.focus();
	}
}



