/*******************************************************************************
* FUNCTION 명 : scwin.fn_retrieveGwanriNo
* FUNCTION 기능설명 : 관리번호를 읽어온다.
*******************************************************************************/
scwin.fn_retrieveGwanriNo = async function(v_FromTo) {

	var v_Flag = "click";
	var v_Param = "";
	if (v_FromTo == "from") {
		v_Param = "v_Saeopjang_Gwanri_No=" + dma_GyeoljaehamJohoeJogeon.get("FROM_GWANRI_NO");
	} else if(v_FromTo == "to") {
		v_Param = "v_Saeopjang_Gwanri_No=" + dma_GyeoljaehamJohoeJogeon.get("TO_GWANRI_NO");
	}

	var v_GwanriNoInfo = new Array();
		v_GwanriNoInfo = await com.cfn_GetSaeopjangInfo(v_Flag, v_Param);

	if (!com.gfn_IsNull(v_GwanriNoInfo[0])) {
		if (v_FromTo == "from") {
			dma_GyeoljaehamJohoeJogeon.set("FROM_GWANRI_NO", v_GwanriNoInfo[2]);
			edt_GyeoljaehamJohoeJogeon_gwanriNo2.focus();
		} else if(v_FromTo == "to") {
			dma_GyeoljaehamJohoeJogeon.set("TO_GWANRI_NO", v_GwanriNoInfo[2]);
			cob_GyeoljaehamJohoeJogeon_noFg.focus();
		}
	}
};



