/*******************************************************************************
* FUNCTION 명 : scwin.btn_Johoe_onclick
* FUNCTION 기능설명 : 결재함조회
*******************************************************************************/
scwin.btn_Johoe_onclick = async function(e, flag) {

	scwin.fv_JehanTmYn = "";
	if (!com.gfn_CheckValid(grp_Search, dma_GyeoljaehamJohoeJogeon)) {
		if (dma_GyeoljaehamJohoeJogeon.get("JEOPSU_NO_YN") == "Y" && com.gfn_IsNull(dma_GyeoljaehamJohoeJogeon.get("FROM_GIJUN_JEOPSU_NO"))) {
			mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.setValue(scwin.fv_GijunJeopsuNo);
		}
		return;
	}

	if (dma_GyeoljaehamJohoeJogeon.get("NO_FG") == "1") {
		edt_GyeoljaehamJohoeJogeon_noFg2.setValue(edt_GyeoljaehamJohoeJogeon_noFg1.getValue())
	}

	if (!await scwin.fn_ValidationRetrieveGyeoljaeham()) {
		return;
	}

	//조회 전 그리드 바인딩된 데이터셋 초기화 (재조회 가능을 위하여)
	if (dma_GyeoljaehamJohoeJogeon.get("MENU_FG") == "1") {
        //결재함
		//결재함탭일 경우, 선택사항 validation 체크
		var comArr = ["edt_GyeoljaehamJohoeJogeon_userFg1"];
		var msgArr = ["담당자"];

		if (!com.gfn_IsNull(cob_GyeoljaehamJohoeJogeon_userFg.getValue())) {
			if (!com.gfn_CheckRequired(comArr,msgArr)) {
				return;
			}
		}

		dlt_GyeoljaehamMokrok.removeAll();
		scwin.fv_GyeoljaehamFilter = 0;
		scwin.fv_GyeoljaehamJohoeCnt = 0;
		scwin.fv_GyeoljaehamAftGyeoljaeCnt = 0;
		scwin.fv_BanryeohamAftGyeoljaeCnt = 0;
		st_totalCnt1.setValue("총 <strong>0</strong>건");

	} else if (dma_GyeoljaehamJohoeJogeon.get("MENU_FG") == "2") {
        //접수함
		dlt_JeopsuhamMokrok.removeAll();
		scwin.fv_JeopsuhamFilter = 0;
		scwin.fv_JeopsuhamJohoeCnt = 0;
		scwin.fv_JeopsuhamAftGyeoljaeCnt = 0;
		scwin.fv_JeopsuhamMokrokTotCnt = 0;
		st_totalCnt2.setValue("총 <strong>0</strong>건");

	} else if (dma_GyeoljaehamJohoeJogeon.get("MENU_FG") == "3") {
        //결재중
		dlt_GyeoljaejungMokrok.removeAll();
		scwin.fv_GyeoljaejungFilter = 0;
		scwin.fv_GyeoljaejungJohoeCnt = 0;
		st_totalCnt3.setValue("총 <strong>0</strong>건");

	} else if (dma_GyeoljaehamJohoeJogeon.get("MENU_FG") == "4") {
        //반려함
		dlt_BanryeohamMokrok.removeAll();
		scwin.fv_BanryeohamFilter = 0;
		scwin.fv_BanryeohamJohoeCnt = 0;
		st_totalCnt4.setValue("총 <strong>0</strong>건");

	} else if (dma_GyeoljaehamJohoeJogeon.get("MENU_FG") == "5") {
        //보류함
		dlt_BoryuhamMokrok.removeAll();
		scwin.fv_BoryuhamFilter = 0;
		scwin.fv_BoryuhamJohoeCnt = 0;
		st_totalCnt5.setValue("총 <strong>0</strong>건");

	} else if (dma_GyeoljaehamJohoeJogeon.get("MENU_FG") == "6") {
        //완결함
		dlt_WangyeolhamMokrok.removeAll();
		scwin.fv_WangyeolhamFilter = 0;
		scwin.fv_WangyeolhamJohoeCnt = 0;
		st_totalCnt6.setValue("총 <strong>0</strong>건");
	}

	scwin.fn_RetrieveGyeoljaeham();
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_RetrieveGyeoljaeham
* FUNCTION 기능설명 : 결재함조회처리
*******************************************************************************/
scwin.fn_RetrieveGyeoljaeham = async function() {

	var v_MenuFg = dma_GyeoljaehamJohoeJogeon.get("MENU_FG");

	var stroutDsList = "";
	var v_PagingDataset = "";
	var pNm = "";

	// - 메뉴구분(탭)에 따른 조회
	if (v_MenuFg == "1") {
        //결재함
		stroutDsList = "['dlt_GyeoljaehamMokrok', 'dma_MokrokRowCountInfo']";
		v_PagingDataset = "ds_GyeoljaehamMokrok";
		pNm = "gv_paging_totalRows_Gyeoljaeham";

		//결재함탭일 경우, 선택사항 validation 체크
		var comArr = ["edt_GyeoljaehamJohoeJogeon_userFg1"];
		var msgArr = ["담당자"];

		if (!com.gfn_IsNull(cob_GyeoljaehamJohoeJogeon_userFg.getValue())) {
			if (!com.gfn_CheckRequired(comArr,msgArr)) {
				return;
			}
		}

	} else if (v_MenuFg == "2") {
        //접수함
		stroutDsList = "['dlt_JeopsuhamMokrok', 'dma_MokrokRowCountInfo']";

	} else if (v_MenuFg == "3") {
        //결재중
		stroutDsList = "['dlt_GyeoljaejungMokrok', 'dma_MokrokRowCountInfo']";

	} else if (v_MenuFg == "4") {
        //반려함
		stroutDsList = "['dlt_BanryeohamMokrok', 'dma_MokrokRowCountInfo']";

	} else if (v_MenuFg == "5") { 
        //보류함
		stroutDsList = "['dlt_BoryuhamMokrok', 'dma_MokrokRowCountInfo']";

	} else if (v_MenuFg == "6") {
        //완결함
		stroutDsList = "['dlt_WangyeolhamMokrok', 'dma_MokrokRowCountInfo']";
	}

	var srvId		 = "RetrieveGyeoljaehamCmd";
	var strURL		 = "/cm/cm02/0101/CM0201100M_E002.do";
	var strinDsList	 = "['dma_GyeoljaehamJohoeJogeon']";
	var strArgument	 = "";
	var strCallback  = scwin.fn_CallBack;

    if (com.gfn_CheckValid(grp_Search, dma_GyeoljaehamJohoeJogeon)) {
		//조회 시 속도문제로 그리드가 한번에 보이지 않는 문제 해결을 위하여
		if (scwin.fv_GyeoljaehamJohoeCnt == 0) {
			// dlt_GyeoljaehamMokrok.setBroadcast(false);
		} else if(scwin.fv_JeopsuhamJohoeCnt == 0) {
			// dlt_JeopsuhamMokrok.setBroadcast(false);
		} else if(scwin.fv_GyeoljaejungJohoeCnt == 0) {
			// dlt_GyeoljaejungMokrok.setBroadcast(false);
		} else if(scwin.fv_BanryeohamJohoeCnt == 0) {
			// dlt_BanryeohamMokrok.setBroadcast(false);
		} else if(scwin.fv_BoryuhamJohoeCnt == 0) {
			// dlt_BoryuhamMokrok.setBroadcast(false);
		} else if(scwin.fv_WangyeolhamJohoeCnt == 0) {
			// dlt_WangyeolhamMokrok.setBroadcast(false);
		}

		await com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, false, true, true);

		//필터 적용한 뒤 다시 조회시, 필터처리 중복조회 문제 해결을 위하여...2
		if (v_MenuFg == "1" && scwin.fv_GyeoljaehamFilter == 1) {
            //결재함
			com.dataListFilter("dlt_GyeoljaehamMokrok", "JEOPSU_NO==GIJUN_JEOPSU_NO")

		} else if (v_MenuFg == "2" && scwin.fv_JeopsuhamFilter == 1) {
            //접수함
			com.dataListFilter("dlt_JeopsuhamMokrok", "JEOPSU_NO==GIJUN_JEOPSU_NO");

		} else if (v_MenuFg == "3" && scwin.fv_GyeoljaejungFilter == 1) {
            //결재중
			com.dataListFilter("dlt_GyeoljaejungMokrok", "JEOPSU_NO==GIJUN_JEOPSU_NO");

		} else if (v_MenuFg == "4" && scwin.fv_BanryeohamFilter == 1) {
            //반려함
			com.dataListFilter("dlt_BanryeohamMokrok", "JEOPSU_NO==GIJUN_JEOPSU_NO");

		} else if (v_MenuFg == "5" && scwin.fv_BoryuhamFilter == 1) {
            //보류함
			com.dataListFilter("dlt_BoryuhamMokrok", "JEOPSU_NO==GIJUN_JEOPSU_NO");

		} else if (v_MenuFg == "6" && scwin.fv_WangyeolhamFilter == 1) {
            //완결함
			com.dataListFilter("dlt_WangyeolhamMokrok", "JEOPSU_NO==GIJUN_JEOPSU_NO");
		}

		//기준접수번호 세팅
		if (com.gfn_IsNull(mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.getValue())) {
			mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.setValue(scwin.fv_GijunJeopsuNo);
		}

		if (dma_GyeoljaehamJohoeJogeon.get("JEOPSU_NO_YN") != "Y") {
			if (com.gfn_IsNull(mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.getValue())) {
				mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.setValue(scwin.fv_GijunJeopsuNo);
			}
		}
    }

    //기준접수번호로 조회 버튼 클릭 후
    if (dma_GyeoljaehamJohoeJogeon.get("JEOPSU_NO_YN") == "Y" && com.gfn_IsNull(dma_GyeoljaehamJohoeJogeon.get("FROM_GIJUN_JEOPSU_NO"))) {
		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.setValue(scwin.fv_GijunJeopsuNo);
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_ValidationRetrieveGyeoljaeham
* FUNCTION 기능설명 : 결재함조회 전 유효성 체크
*******************************************************************************/
scwin.fn_ValidationRetrieveGyeoljaeham = async function() {

	//기준접수번호or접수번호의 length가 덜 채워졌을경우 clear
	if (dma_GyeoljaehamJohoeJogeon.get("FROM_GIJUN_JEOPSU_NO").length < 15) {
		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.setValue("");
	}
	if (dma_GyeoljaehamJohoeJogeon.get("TO_GIJUN_JEOPSU_NO").length < 15) {
		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.setValue("");
	}

	//처리일자 From, To valildation
	var strDt = "처리일자";
    if (!com.gfn_VaildFromTo(edt_GyeoljaehamJohoeJogeon_cheoriDt, edt_GyeoljaehamJohoeJogeon_cheoriDt1, strDt)) {
		return false;
    }

    //처리일자 From, To 20일 차이 validation
    var v_ToDt20 = com.addDate(edt_GyeoljaehamJohoeJogeon_cheoriDt.getValue(), 20);
    if (edt_GyeoljaehamJohoeJogeon_cheoriDt1.getValue() > v_ToDt20) {
		var v_MsgArray = ["처리일자 조회기간", "20일"];
		await com.gfn_MsgAlert("MAAA066", v_MsgArray);
		edt_GyeoljaehamJohoeJogeon_cheoriDt1.focus();
		return false;
    }

    //관리번호 From, To valildation
    var strDt = "관리번호";
    if (!com.gfn_VaildFromTo(edt_GyeoljaehamJohoeJogeon_gwanriNo, edt_GyeoljaehamJohoeJogeon_gwanriNo2, strDt)) {
		return false;
    }

    //기준접수번호(접수번호) From, To valildation
    var strDt = st_GyeoljaehamJohoeJogeon_gijunJeopsuNo.Text;
    if (chk_GyeoljaehamJohoeJogeon_jeopsuNoYn.getValue() == "N" && !com.gfn_VaildFromTo(mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo, mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1, strDt)) {
		return false;
    }

    //번호구분 From, To valildation
    var strDt = cob_GyeoljaehamJohoeJogeon_noFg.getValue();
    if (!com.gfn_VaildFromTo(edt_GyeoljaehamJohoeJogeon_noFg1, edt_GyeoljaehamJohoeJogeon_noFg2, strDt)) {
		return false;
    }
    if (!com.gfn_VaildFromTo(edt_GyeoljaehamJohoeJogeon_noFg1, edt_GyeoljaehamJohoeJogeon_noFg2, strDt)) {
		return false;
    }

    //사업장원부번호 From, To valildation
    if (com.gfn_IsNull(dma_GyeoljaehamJohoeJogeon.get("FROM_SE_WONBU_NO")) && !com.gfn_IsNull(dma_GyeoljaehamJohoeJogeon.get("TO_SE_WONBU_NO"))) {
		dma_GyeoljaehamJohoeJogeon.set("FROM_SE_WONBU_NO", dma_GyeoljaehamJohoeJogeon.get("TO_SE_WONBU_NO"));
	} else if (com.gfn_IsNull(dma_GyeoljaehamJohoeJogeon.get("TO_SE_WONBU_NO")) && !com.gfn_IsNull(dma_GyeoljaehamJohoeJogeon.get("FROM_SE_WONBU_NO"))) {
		dma_GyeoljaehamJohoeJogeon.set("TO_SE_WONBU_NO", dma_GyeoljaehamJohoeJogeon.get("FROM_SE_WONBU_NO"));
	}

	return true;
};



/*******************************************************************************
* FUNCTION 명 : scwin.btn_IlgwalCheck_Seungin_onclick
* FUNCTION 기능설명 : 일괄체크 - 승인
*******************************************************************************/
scwin.btn_IlgwalCheck_Seungin_onclick = async function(e) {
	if (tab1.getSelectedTabIndex() == 1) {
        //접수함일때 조회된 목록의 결재구분을 일괄적으로 결재로 선택한다.
		if (!await scwin.fn_CheckIlgwalCheckJehan("N")) {
			await com.gfn_Alert("보수총액신고 집중기간으로 노동보험시스템 부하 방지를 위해 일괄결재처리(개별결재 가능)를 제한하오니 양해하여 주시기 바랍니다.");
			return;
		}

		for (var inx=0; inx < dlt_JeopsuhamMokrok.getRowCount(); inx++) {
			dlt_JeopsuhamMokrok.setCellData(inx, "GYEOLJAE", "1");
			dlt_JeopsuhamMokrok.setCellData(inx, "GYEOLJAE_FG", "1");
			dlt_JeopsuhamMokrok.setCellData(inx, "BORYU", "0");
			dlt_JeopsuhamMokrok.setCellData(inx, "MIGYEOL", "0");
		}

	} else if (tab1.getSelectedTabIndex() == 0) {
        //결재함일때 조회된 목록의 결재구분을 일괄적으로 승인으로 선택한다.
		if (!await scwin.fn_CheckIlgwalCheckJehan("N")) {
			await com.gfn_Alert("보수총액신고 집중기간으로 노동보험시스템 부하 방지를 위해 일괄결재처리(개별결재 가능)를 제한하오니 양해하여 주시기 바랍니다.");
			return;
		}

		for(var inx=0; inx < dlt_GyeoljaehamMokrok.getRowCount(); inx++) {
		    //최초요양이면서 결재직급이 지사장 또는 부장 이고  리스크리포트 2건이상일때 일괄 승인체크 못하도록 개선(2014.07.11)
		    var vGyeoljaeJikeupCd = await com.gfn_SsGyeoljaeJikgeupCd();

		    if (dlt_GyeoljaehamMokrok.getCellData(inx, "MINWON_DOC_CD") == "1001" && (vGyeoljaeJikeupCd == "10" || vGyeoljaeJikeupCd == "20")) {
			    var vYoyakInfo = dlt_GyeoljaehamMokrok.getCellData(inx, "YOYAK_INFO");
				var vBokhapGwanriDaesang = vYoyakInfo.substr(vYoyakInfo.indexOf("복합관리대상여부") + 10, 1);

				//복합관리대상여부 (리스크리포트에서 복합관리대상으로 변경 2016.06.27)
				if (vBokhapGwanriDaesang == "예") {
					tab1.setSelectedTabIndex(0);
					grd_GyeoljaehamMokrok.setFocusedCell(inx, 9, true)

					await com.gfn_Alert("최초요양 복합관리대상인 경우 일괄 승인 처리가 불가능합니다.");
					return false;
				}
		    }

			dlt_GyeoljaehamMokrok.setCellData(inx, "SEUNGIN", "1");
			dlt_GyeoljaehamMokrok.setCellData(inx, "GYEOLJAE_FG", "1");
			dlt_GyeoljaehamMokrok.setCellData(inx, "BORYU", "0");
			dlt_GyeoljaehamMokrok.setCellData(inx, "BANRYO", "0");
			dlt_GyeoljaehamMokrok.setCellData(inx, "MIGYEOL", "0");
		}

	} else if (tab1.getSelectedTabIndex() == 2) {
        //결재중일때 조회된 목록의 결재구분을 일괄적으로 회수로 선택한다.
		for (var inx=0; inx < dlt_GyeoljaejungMokrok.getRowCount(); inx++) {
			dlt_GyeoljaejungMokrok.setCellData(inx, "HEOUSU", "1");
			dlt_GyeoljaejungMokrok.setCellData(inx, "GYEOLJAE_FG", "4");
			dlt_GyeoljaejungMokrok.setCellData(inx, "BONINBANRYO", "0");
			dlt_GyeoljaejungMokrok.setCellData(inx, "MIGYEOL", "0");
		}

	} else if (tab1.getSelectedTabIndex() == 3) {
        //반려함일때 조회된 목록의 체크박스를 선택한다.
		for (var inx=0; inx < dlt_BanryeohamMokrok.getRowCount(); inx++) {
			dlt_BanryeohamMokrok.setCellData(inx, "CHECK", 1);
		}
		// grd_BanryeohamMokrok.Redraw = true;

	} else if (tab1.getSelectedTabIndex() == 4) {
        //보류함일때 조회된 목록의 체크박스를 선택한다.
		for (var inx=0; inx < dlt_BoryuhamMokrok.getRowCount(); inx++) {
			dlt_BoryuhamMokrok.setCellData(inx, "CHECK", 1);
		}
	}
};



