/*******************************************************************************
* FUNCTION 명 : scwin.fn_ValidaionChk
* FUNCTION 기능설명 : 조회된 결과가 하나도 없을때 or 선택된 체크박스가 하나도 없을때 유효성 체크
*******************************************************************************/
scwin.fn_ValidaionChk = async function() {
	var v_MenuFg = dma_GyeoljaehamJohoeJogeon.get("MENU_FG");
	var v_ChkCnt = 0;

	//조회된 결과가 하나도 없을때
	if (v_MenuFg == 1 && dlt_GyeoljaehamMokrok.getRowCount() == 0) {

		var v_MsgArray = ["선택된 행"];
		await com.gfn_MsgAlert("MZZA150", v_MsgArray);
		return false;

	} else if (v_MenuFg == 2 && dlt_JeopsuhamMokrok.getRowCount() == 0) {

		var v_MsgArray = ["선택된 행"];
		await com.gfn_MsgAlert("MZZA150", v_MsgArray);
		return false;

	} else if (v_MenuFg == 3 && dlt_GyeoljaejungMokrok.getRowCount() == 0) {

		var v_MsgArray = ["선택된 행"];
		await com.gfn_MsgAlert("MZZA150", v_MsgArray);
		return false;

	} else if (v_MenuFg == 4 && dlt_BanryeohamMokrok.getRowCount() == 0) {

		var v_MsgArray = ["선택된 행"];
		await com.gfn_MsgAlert("MZZA150", v_MsgArray);
		return false;

	} else if (v_MenuFg == 5 && dlt_BoryuhamMokrok.getRowCount() == 0) {

		var v_MsgArray = ["선택된 행"];
		await com.gfn_MsgAlert("MZZA150", v_MsgArray);
		return false;

	} else if (v_MenuFg == 6 && dlt_WangyeolhamMokrok.getRowCount() == 0) {

		var v_MsgArray = ["선택된 행"];
		await com.gfn_MsgAlert("MZZA150", v_MsgArray);
		return false;

	} else if (v_MenuFg == 4) {
        //선택된 체크박스가 하나도 없을때
		com.dataListFilter("dlt_BanryeohamMokrok", "CHECK == '1'");
		v_ChkCnt = dlt_BanryeohamMokrok.getRowCount();
		dlt_BanryeohamMokrok.clearFilter();

		if (v_ChkCnt == 0) {
			var v_MsgArray = ["선택된 행"];
			await com.gfn_MsgAlert("MZZA150", v_MsgArray);
			return false;
		}

	} else if (v_MenuFg == 5) {

		com.dataListFilter("dlt_BoryuhamMokrok", "CHECK == '1'");
		v_ChkCnt = dlt_BoryuhamMokrok.getRowCount();
		dlt_BoryuhamMokrok.clearFilter();

		if (v_ChkCnt == 0) {
			var v_MsgArray = ["선택된 행"];
			await com.gfn_MsgAlert("MZZA150", v_MsgArray);
			return false;
		}
	}

	return true;
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_CheckPassword
* FUNCTION 기능설명 : 결재암호 유효성 체크
*******************************************************************************/
scwin.fn_CheckPassword = async function() {
	dma_IlgwalCheck.set("USER_ID", com.gfn_SsGetId());

	var srvId		 = "RetrieveCheckGyeoljaePwCmd";
	var strURL		 = "/cm/cm02/0101/CM0201100M_E003.do";
	var strinDsList  = "['dma_IlgwalCheck']";
	var stroutDsList = "['dma_GyeoljaeInfo']";
	var strArgument	 = "";
	var strCallback  = scwin.fn_CallBack;

	await com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, false, true, true);
};



/*******************************************************************************
* FUNCTION 명 : scwin.btn_IlgwalCheck_GyeoljaeCheori_onclick
* FUNCTION 기능설명 : 결재처리 버튼 클릭시
*******************************************************************************/
scwin.btn_IlgwalCheck_GyeoljaeCheori_onclick = async function(e) {

	//조회된 결과가 하나도 없을때 or 선택된 체크박스가 하나도 없을때 validation
	if (!await scwin.fn_ValidaionChk()) {
		return;
	}

	//보총집중기간중 일괄결재 제한
	var v_OverJehanCntYn = false;
	if (dma_IlgwalCheck.get("MENU_FG") == 1) {

		var caseCount = 0;
		for (var i=0 ; i<dlt_GyeoljaehamMokrok.getRowCount(); i++) {
			if(dlt_GyeoljaehamMokrok.getCellData(i, "YN") != "Y" && dlt_GyeoljaehamMokrok.getCellData(i, "GYEOLJAE_FG") != "1") {
				caseCount++;
			}
		}

		if (caseCount > scwin.fv_JehanCnt) {
			v_OverJehanCntYn = true;
		}

	} else if (dma_IlgwalCheck.get("MENU_FG") == 2) {

		var caseCount = 0;
		for (var i=0 ; i<dlt_JeopsuhamMokrok.getRowCount(); i++) {
			if(dlt_JeopsuhamMokrok.getCellData(i, "YN") != "Y" && dlt_JeopsuhamMokrok.getCellData(i, "GYEOLJAE_FG") != "1") {
				caseCount++;
			}
		}

		if (caseCount > scwin.fv_JehanCnt) {
			v_OverJehanCntYn = true;
		}
	}

	if (v_OverJehanCntYn) {
		if (!scwin.fn_CheckIlgwalCheckJehan()) {
			return;
		}
	}

	//결재암호가 없을 시 MZZA068 메시지 출력
	if (com.gfn_IsNull(edt_IlgwalCheck_gyeoljaePw.getValue())) {
		var v_MsgArray = ["결재암호"];
		await com.gfn_MsgAlert("MZZA068", v_MsgArray);
		return;
	}

	var v_MenuFg = dma_IlgwalCheck.get("MENU_FG");

	//전부 미결로 선택 후 결재처리시 MBBA016 메시지 출력
	if (v_MenuFg == 1) {

        //결재함
		if (!await scwin.fn_NotMigyeolGyeoljaeham()) {
			return;
		}

	} else if (v_MenuFg == 2) {

        //접수함
		if (!await scwin.fn_NotMigyeolJeopsuham()) {
			return;
		}

	} else if (v_MenuFg == 3) {

        //결재중
		if (!await scwin.fn_NotMigyeolGyeoljaejung()) {
			return;
		}
	}

	//결재암호 유효성 체크
	dma_GyeoljaeInfo.setEmptyValue();
	scwin.fn_CheckPassword();
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_NotMigyeolGyeoljaeham
* FUNCTION 기능설명 : 전부 미결로 선택 후 결재처리시 메시지 출력 (결재함)
*******************************************************************************/
scwin.fn_NotMigyeolGyeoljaeham = async function() {

	var v_NotMigyeolGyeoljaeCnt = dlt_GyeoljaehamMokrok.getUnmatchedIndex("GYEOLJAE_FG", "0", true, 0, dlt_GyeoljaehamMokrok.getRowCount()).length;
	if (v_NotMigyeolGyeoljaeCnt == 0) {
		await com.gfn_MsgAlert("MQBA016");		//선택된 결재처리 대상이 없습니다.
		return false;
	}
	return true;

};



