/*******************************************************************************
* FUNCTION 명 : scwin.fn_HandleGyeoljae
* FUNCTION 기능설명 : 결재처리
*******************************************************************************/
scwin.fn_HandleGyeoljae = async function() {

	scwin.fv_GyeoljaeBunhalFg = false;

	if(tab1.getSelectedTabIndex() == "0" || tab1.getSelectedTabIndex() == "1" || tab1.getSelectedTabIndex() == "2") {
		scwin.fn_ErrorMokrokInit(tab1.getSelectedTabIndex());
	}

	// - 메뉴구분에 따른 결재처리
	//기준접수번호 == 접수번호 인 Dataset 또는 체크된 row만 결재처리 수행
	if (dma_IlgwalCheck.get("MENU_FG") == "1") {

        //결재함
		if(typeof(dlt_MokrokInfoTmp) == 'undefined') {
			com.create('dlt_MokrokInfoTmp', dlt_GyeoljaehamMokrok.getAllArray().columnInfo);
		} else {
			$p.data.remove('dlt_MokrokInfoTmp');
			com.create('dlt_MokrokInfoTmp', dlt_GyeoljaehamMokrok.getAllArray().columnInfo);
		}

		scwin.fv_GyeoljaeBunhalFg = true;
		dlt_GyeoljaehamMokrok.setBroadcast(false);		//Dataset에 Filter를 적용시켰을 때 그리드에 반영시키지 않기 위하여
		com.dataListFilter("dlt_GyeoljaehamMokrok", "YN=='N' && GYEOLJAE_FG!='0'");		//기준접수번호 == 접수번호 && 미결을 제외한 Dataset
		dlt_MokrokInfoTmp.setJSON(dlt_GyeoljaehamMokrok.getAllFilteredJSON());
		dlt_GyeoljaehamMokrok.clearFilter();
		scwin.fv_ResultTextCom = st_st1;
		scwin.fv_CheoriDsObj = dlt_GyeoljaehamMokrok;
		dlt_GyeoljaehamMokrok.setBroadcast(true);

	} else if (dma_IlgwalCheck.get("MENU_FG") == "2") {

        //접수함
		if(typeof(dlt_MokrokInfoTmp) == 'undefined') {
			com.create('dlt_MokrokInfoTmp', dlt_JeopsuhamMokrok.getAllArray().columnInfo);
		} else {
			$p.data.remove('dlt_MokrokInfoTmp');
			com.create('dlt_MokrokInfoTmp', dlt_JeopsuhamMokrok.getAllArray().columnInfo);
		}

		scwin.fv_GyeoljaeBunhalFg = true;	//20101228 접수함도 분할처리 추가
		dlt_JeopsuhamMokrok.setBroadcast(false);	//Dataset에 Filter를 적용시켰을 때 그리드에 반영시키지 않기 위하여
		com.dataListFilter("dlt_JeopsuhamMokrok", "YN=='N' && GYEOLJAE_FG!='0'");	//기준접수번호 == 접수번호 && 미결을 제외한  Dataset
		dlt_MokrokInfoTmp.setJSON(dlt_JeopsuhamMokrok.getAllFilteredJSON());
		dlt_JeopsuhamMokrok.clearFilter();
		scwin.fv_CheoriDsObj = dlt_JeopsuhamMokrok;
		scwin.fv_ResultTextCom = st_st2;
		dlt_JeopsuhamMokrok.setBroadcast(true);

	} else if (dma_IlgwalCheck.get("MENU_FG") == "3") {

        //결재중
		if(typeof(dlt_MokrokInfoTmp) == 'undefined') {
			com.create('dlt_MokrokInfoTmp', dlt_GyeoljaejungMokrok.getAllArray().columnInfo);
		} else {
			$p.data.remove('dlt_MokrokInfoTmp');
			com.create('dlt_MokrokInfoTmp', dlt_GyeoljaejungMokrok.getAllArray().columnInfo);
		}

		dlt_GyeoljaejungMokrok.setBroadcast(false);		//Dataset에 Filter를 적용시켰을 때 그리드에 반영시키지 않기 위하여
		com.dataListFilter("dlt_GyeoljaejungMokrok", "YN=='N' && GYEOLJAE_FG!='0'");	//기준접수번호 == 접수번호 && 미결을 제외한  Dataset
		dlt_MokrokInfoTmp.setJSON(dlt_GyeoljaejungMokrok.getAllFilteredJSON());
		dlt_GyeoljaejungMokrok.clearFilter();
		scwin.fv_CheoriDsObj = dlt_GyeoljaejungMokrok;
		scwin.fv_ResultTextCom = st_st2;
		dlt_GyeoljaejungMokrok.setBroadcast(true);

	} else if (dma_IlgwalCheck.get("MENU_FG") == "4") {

        //반려함
		if(typeof(dlt_MokrokInfoTmp) == 'undefined') {
			com.create('dlt_MokrokInfoTmp', dlt_BanryeohamMokrok.getAllArray().columnInfo);
		} else {
			$p.data.remove('dlt_MokrokInfoTmp');
			com.create('dlt_MokrokInfoTmp', dlt_BanryeohamMokrok.getAllArray().columnInfo);
		}

		dlt_BanryeohamMokrok.setBroadcast(false);		//Dataset에 Filter를 적용시켰을 때 그리드에 반영시키지 않기 위하여
		com.dataListFilter("dlt_BanryeohamMokrok", "YN=='N' && CHECK=='1'");	//체크박스 선택한 Dataset
		dlt_MokrokInfoTmp.setJSON(dlt_BanryeohamMokrok.getAllFilteredJSON());
