        scwin.fv_LimitCnt = 5;					//분활처리할 건수
        scwin.fv_LoopCnt = parseInt(scwin.fv_PDsRowCnt/scwin.fv_LimitCnt);//
        scwin.fv_GyeoljaehamTotCnt = scwin.fv_CheoriDsObj.getRowCount();
        scwin.fv_ResultCheoriCnt = 0;
        scwin.fv_BunhalCheoriInx = 1;

        if (scwin.fv_LoopCnt < 1) scwin.fv_LoopCnt = 1;

        scwin.fn_GyeoljaeBunhalCheori(scwin.fv_BunhalCheoriInx++);

    } else {

        await com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, false, true, true);

    }
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_ErrorMokrokInit
* FUNCTION 기능설명 : 탭 클릭시 발생하는 이벤트를 처리한다.
*******************************************************************************/
scwin.fn_ErrorMokrokInit = function(v_TabInx) {
	if (v_TabInx == "0") {
		if (dlt_GyeoljaehamMokrok.getRowCount() != 0) {
			for (var i=0 ; i < dlt_GyeoljaehamMokrok.getRowCount() ; i++) {
				dlt_GyeoljaehamMokrok.setCellData(i, "ERROR_NAEYONG", "");
			}
		}

	} else if (v_TabInx == "1") {
		if (dlt_JeopsuhamMokrok.getRowCount() != 0) {
			for (var i=0 ; i < dlt_JeopsuhamMokrok.getRowCount() ; i++) {
				dlt_JeopsuhamMokrok.setCellData(i, "ERROR_NAEYONG", "");
			}
		}

	} else if (v_TabInx == "2") {
		if (dlt_GyeoljaejungMokrok.getRowCount() != 0) {
			for (var i=0 ; i < dlt_GyeoljaejungMokrok.getRowCount() ; i++) {
				dlt_GyeoljaejungMokrok.setCellData(i, "ERROR_NAEYONG", "");
			}
		}
	}
};



