/*******************************************************************************
* FUNCTION 명 : scwin.fn_CallBack
* FUNCTION 기능설명 : Transaction후에 Transaction의 종류에 따라 후처리하는 함수.
*******************************************************************************/
scwin.fn_CallBack = async function(srvId,ErrorCode,ErrorMsg,data) {

	if (ErrorCode < 0) {
		if (scwin.fv_GyeoljaeBunhalFg) {
			scwin.fn_GyeoljaeBunhalCheoriAft();
		} else {
		    return;
		}
	}

	//결재비밀번호변경여부조회 후처리
	if (srvId == "RetrieveGyeoljaePwChangeIlsuCmd") {

		var v_GyeoljaeJikgeupCd = dma_GyeoljaeResultInfo.get("GYEOLJAE_JIKGEUP_CD");

		if (dma_GyeoljaeResultInfo.get("GYEOLJAE_PW_CHANGE_YN") == "Y") {
			await com.gfn_MsgAlert("MQBC001");  //동일한 결재비밀번호를 30일 이상 사용중입니다.\n사용자등록(일반사용자) 화면에서 결재비밀번호를 변경하시기 바랍니다.
		}

		// 포탈 연계 처리인지 확인
		if (scwin.fv_YeonGeyYn=="Y") {
			tab1.setSelectedTabIndex(Number(scwin.fv_TabNo));

			if (scwin.fv_TabNo == "0") {
                //결재함이면
				dma_GyeoljaehamJohoeJogeon.set("MENU_FG", "1");
				dma_IlgwalCheck.set("MENU_FG", "1");

			} else if (scwin.fv_TabNo == "1") {
                //접수함이면
				dma_GyeoljaehamJohoeJogeon.set("MENU_FG", "2");
				dma_IlgwalCheck.set("MENU_FG", "2");

			} else if (scwin.fv_TabNo == "2") {
                //결재중이면
				dma_GyeoljaehamJohoeJogeon.set("MENU_FG", "3");
				dma_IlgwalCheck.set("MENU_FG", "3");

			} else if (scwin.fv_TabNo == "3") {
                //반려함이면
				dma_GyeoljaehamJohoeJogeon.set("MENU_FG", "4");
				dma_IlgwalCheck.set("MENU_FG", "4");
			}

		} else {
			//결재비밀번호변경여부조회 서버이벤트를 통한 결재직급코드에 따라 화면오픈시 탭변경
			if (com.gfn_IsNull(v_GyeoljaeJikgeupCd) || v_GyeoljaeJikgeupCd > "30") {
				tab1.setSelectedTabIndex(1); //접수함 탭으로 이동
				dma_GyeoljaehamJohoeJogeon.set("MENU_FG", "2");
				dma_IlgwalCheck.set("MENU_FG", "2");
			} else if (v_GyeoljaeJikgeupCd <= "30") {
				tab1.setSelectedTabIndex(0); //결재함 탭으로 이동
				dma_GyeoljaehamJohoeJogeon.set("MENU_FG", "1");
				dma_IlgwalCheck.set("MENU_FG", "1");
				com.dataListFilter("dlt_UserFg", "GT_CD != '3'");
			}
		}

		cob_GyeoljaehamJohoeJogeon_minwonFg.focus();

	} else if (srvId == "RetrieveGyeoljaehamCmd") {
        //결재함조회 후처리
		// - 메뉴구분(탭)에 따른 페이징 조회 후처리
		//접수함목록의 조회 총건수를 전역변수에 셋팅
		scwin.fv_JeopsuhamMokrokTotCnt = dma_MokrokRowCountInfo.get("MOKROK_CNT");

		scwin.fn_RetrieveGyeoljaehamCallback(ErrorCode);

	} else if (srvId == "HandleGyeoljaehamGyeoljaeCmd") {
        //결재함결재처리 후처리
		if (scwin.fv_GyeoljaeBunhalFg) {
			for (var inx = 0; inx < dlt_MokrokInfo.getRowCount(); inx++) {
				var v_GijunJeopsuNo = dlt_MokrokInfo.getCellData(inx, "GIJUN_JEOPSU_NO");
				var v_BoheomFg = dlt_MokrokInfo.getCellData(inx, "BOHEOM_FG");
				var v_ErrorNaeyong = dlt_MokrokInfo.getCellData(inx, "ERROR_NAEYONG");
				var v_StrExpr = "GIJUN_JEOPSU_NO=='" + v_GijunJeopsuNo + "' && BOHEOM_FG=='" + v_BoheomFg + "'";
				var v_FindRow = com.gfn_searchRow(scwin.fv_CheoriDsObj, v_StrExpr);

				if (scwin.fv_LogOn && !com.gfn_IsNull(v_ErrorNaeyong)) {
					console.log("v_GijunJeopsuNo 	= " + v_GijunJeopsuNo);
					console.log("v_BoheomFg 		= " + v_BoheomFg);
					console.log("v_ErrorNaeyong 	= " + v_ErrorNaeyong);
					console.log("v_StrExpr 		= " + v_StrExpr);
					console.log("v_FindRow 		= " + v_FindRow);
				}

				if (v_FindRow > -1) {
					scwin.fv_failCnt = scwin.fv_failCnt + 1;
					console.log("ERROR_NAEYONG setting!");
					scwin.fv_CheoriDsObj.setCellData(v_FindRow, "ERROR_NAEYONG", v_ErrorNaeyong);
				}
			}

			scwin.fv_ResultCheoriCnt = scwin.fv_ResultCheoriCnt + parseInt(dma_ResultInfo.get("CHEORI_CNT")); 	//처리건수 세팅
			scwin.fv_ResultTextCom.setValue("결재진행중입니다! 총 결재대상건수 [" + scwin.fv_GyeoljaehamTotCnt + " 건]  선택건수처리상태 [" + scwin.fv_EndInx + "건 / 총 " + scwin.fv_PDsRowCnt + "건]  결재건수 [" + scwin.fv_ResultCheoriCnt + " 건]");
			// console.log("타이머 시작 : " + scwin.fn_GetDate());

			// SetTimer(2, 3000); //2:타이머 번호, 5000:발생 시간(밀리세컨)
			$p.setInterval(function(){scwin.fn_OnTimer(2);}, {delay:5000, key:"qb0101_Timer01"});

		} else {

			//결재처리 후 결재비밀번호 초기화
			edt_IlgwalCheck_gyeoljaePw.setValue("");
			edt_IlgwalCheck_gyeoljaePw.focus();

			if (dma_IlgwalCheck.get("MENU_FG") == "4" || dma_IlgwalCheck.get("MENU_FG") == "5") {

				scwin.btn_Johoe_onclick();

			} else {
				//PC 처리 후 out으로 나온 dlt_MokrokInfo의 ERROR_NAEYONG를 그리드의 에러내용에 바인딩시키기 / 메뉴구분에 따라 목록건수, 선택건수, 처리건수 세팅
				var v_geonsu = new Array();
				v_geonsu = scwin.fn_SetErrorMessage();
				//결재처리 후 에러내용이 없는 것은 deleterow 하여 에러내용이 있는것만 그리드에서 출력
				scwin.fn_DeleteRow();

				// console.log("\n########################## => END TIME : " + com.gfn_GetDateTime() + " <= #########################\n");
				var v_param = "fv_MokrokCnt=" + v_geonsu[0];
				v_param += " fv_SeontaekCnt=" + v_geonsu[1];
				v_param += " fv_CheoriCnt=" + v_geonsu[2];
				com.gfn_Dialog("/ui/sia/biz/cm/cm02/0101/CM0201111P.xml",v_param, 410, 260, "기준접수번호 처리 결과");
			}
		}

	} else if (srvId == "RetrieveDaegyeoljaGeuntaeCmd") {

        //대결할자 선택  후처리
		if (!com.gfn_IsNull(dlt_GeuntaeInfo.getCellData(0, "DAEGYEOLJA_ID"))) {
			if(dlt_GeuntaeInfo.getCellData(0, "GEUNTAE_FG") == "N") {
				await com.gfn_MsgAlert("MQBA013");	//대결할자가 공석중이 아니므로 선택할 수 없습니다

				cob_GyeoljaehamJohoeJogeon_userFg.focus();
			} else {
				edt_GyeoljaehamJohoeJogeon_userFg1.setValue(dlt_GeuntaeInfo.getCellData(0, "DAEGYEOLJA_ID"));
				edt_GyeoljaehamJohoeJogeon_userFg3.setValue(dlt_GeuntaeInfo.getCellData(0, "DAEGYEOLJA_NM"));

				edt_GyeoljaehamJohoeJogeon_cheoriDt.focus();
			}

		} else {

			await com.gfn_MsgAlert("MQBA014");		//대결할자를 등록하고 처리하십시요

			cob_GyeoljaehamJohoeJogeon_userFg.focus();
		}

	} else if(srvId = "RetrieveCheckGyeoljaePwCmd") {

        //결재암호 유효성 체크 후처리
		if (dma_GyeoljaeInfo.get("GYEOLJAE_GANUNG_YN") == "Y") {
			//결재암호가 유효할 경우 결재처리 수행
			scwin.fn_HandleGyeoljae();
		} else {
			//결재암호가 유효하지 않을 경우 결재처리 미수행 및 Alert 창 띄워줌
			await com.gfn_MsgAlert("MQBA015");
			edt_IlgwalCheck_gyeoljaePw.setValue("");
			edt_IlgwalCheck_gyeoljaePw.focus();
		}
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_DeleteRow
* FUNCTION 기능설명 : 결재처리 후 에러내용이 없는 것은 deleterow를 하여 결재 후처리에서 에러내용이 있는것만 그리드에서 출력
*******************************************************************************/
scwin.fn_DeleteRow = function() {

	//메뉴구분에 따라서 처리
	if(dma_IlgwalCheck.get("MENU_FG") == "1") {
        //결재함
		if(typeof(dlt_DeleteJeopsuNo) == 'undefined') {
			com.create('dlt_DeleteJeopsuNo', dlt_GyeoljaehamMokrok.getAllArray().columnInfo);
		} else {
			$p.data.remove('dlt_DeleteJeopsuNo');
			com.create('dlt_DeleteJeopsuNo', dlt_GyeoljaehamMokrok.getAllArray().columnInfo);
		}

		dlt_GyeoljaehamMokrok.setBroadcast(false);		//Dataset에 Filter를 적용시켰을 때 그리드에 반영시키지 않기 위하여
		com.dataListFilter("dlt_GyeoljaehamMokrok", "ERROR_NAEYONG=='' && GYEOLJAE_FG!='0'");
		scwin.fv_GyeoljaehamAftGyeoljaeCnt = dlt_GyeoljaehamMokrok.getRowCount();
		dlt_DeleteJeopsuNo.setJSON(dlt_GyeoljaehamMokrok.getAllFilteredJSON());

		var v_FindIndexSave = "";	//v_FindIndex가 -1로 세팅될 경우 유효한 예전값으로 원복시키기 위한 값
		var v_FindIndex = -2;		//SearchRow의 결과값 (제일 첫줄 설정을 -2로)

		var delSelectedRow = new Array();
		for (var i=0; i < dlt_DeleteJeopsuNo.getRowCount(); i++) {
			var v_DeleteJeopsuNo = dlt_DeleteJeopsuNo.getCellData(i, "GIJUN_JEOPSU_NO");
			if (v_FindIndex == -1) {
				v_FindIndex = v_FindIndexSave;
			}

			while (v_FindIndex != -1) {
				if (v_FindIndex == -2) {
                    //v_FindIndex가 제일 첫줄일 경우, 첫줄부터 SearchRow 수행
					v_FindIndex = com.gfn_searchRow(dlt_GyeoljaehamMokrok, "GIJUN_JEOPSU_NO=='"+v_DeleteJeopsuNo+"'");
				} else {
                    //v_FindIndex를 이미 찾은 경우, 해당 index 다음부터 SearchRow 수행 (접수번호!=기준접수번호 인것을 Deleterow하기 위하여)
					v_FindIndex = com.gfn_searchRow(dlt_GyeoljaehamMokrok, "GIJUN_JEOPSU_NO=='"+v_DeleteJeopsuNo+"'", v_FindIndex+1);
				}

				//SearchRow가 유효한 값(표현식에 맞는 row의 index)를 반환했을 경우 DeleteSelected를 위한 SelectRow
				if (v_FindIndex != -1) {
					delSelectedRow.push(v_FindIndex);
					v_FindIndexSave = v_FindIndex;
				}
			}
		}

		//위 구문을 통해 SelectRow된 행(미결이 아니면서 에러내용이 없는 접수번호를 가진 row)를 삭제한다
		dlt_GyeoljaehamMokrok.clearFilter();
		dlt_GyeoljaehamMokrok.setBroadcast(true);
		dlt_GyeoljaehamMokrok.removeRows(delSelectedRow);

		st_totalCnt1.setValue("총 <strong>" + dlt_GyeoljaehamMokrok.getRowCount() + "</strong>건");

	} else if (dma_IlgwalCheck.get("MENU_FG") == "2") {

        //접수함
		if(typeof(dlt_DeleteJeopsuNo) == 'undefined') {
			com.create('dlt_DeleteJeopsuNo', dlt_JeopsuhamMokrok.getAllArray().columnInfo);
		} else {
			$p.data.remove('dlt_DeleteJeopsuNo');
			com.create('dlt_DeleteJeopsuNo', dlt_JeopsuhamMokrok.getAllArray().columnInfo);
		}

		dlt_JeopsuhamMokrok.setBroadcast(false);		//Dataset에 Filter를 적용시켰을 때 그리드에 반영시키지 않기 위하여
		com.dataListFilter("dlt_JeopsuhamMokrok", "ERROR_NAEYONG=='' && GYEOLJAE_FG!='0'");
		scwin.fv_JeopsuhamAftGyeoljaeCnt = dlt_JeopsuhamMokrok.getRowCount();

		dlt_DeleteJeopsuNo.setJSON(dlt_JeopsuhamMokrok.getAllFilteredJSON());

		var v_FindIndexSave = "";	//v_FindIndex가 -1로 세팅될 경우 유효한 예전값으로 원복시키기 위한 값
		var v_FindIndex = -2;		//SearchRow의 결과값 (제일 첫줄 설정을 -2로)

		var delSelectedRow = new Array();
		for (var i=0; i<dlt_DeleteJeopsuNo.getRowCount(); i++) {
			var v_DeleteJeopsuNo = dlt_DeleteJeopsuNo.getCellData(i, "GIJUN_JEOPSU_NO");
			if (v_FindIndex == -1) {
				v_FindIndex = v_FindIndexSave;
			}

			while (v_FindIndex != -1) {
				if (v_FindIndex == -2) {
                    //v_FindIndex가 제일 첫줄일 경우, 첫줄부터 SearchRow 수행
					v_FindIndex = com.gfn_searchRow(dlt_JeopsuhamMokrok, "GIJUN_JEOPSU_NO=='"+v_DeleteJeopsuNo+"'");
				} else {
                    //v_FindIndex를 이미 찾은 경우, 해당 index 다음부터 SearchRow 수행 (접수번호!=기준접수번호 인것을 Deleterow하기 위하여)
					v_FindIndex = com.gfn_searchRow(dlt_JeopsuhamMokrok, "GIJUN_JEOPSU_NO=='"+v_DeleteJeopsuNo+"'", v_FindIndex+1);
				}

				//SearchRow가 유효한 값(표현식에 맞는 row의 index)를 반환했을 경우 DeleteSelected를 위한 SelectRow
				if (v_FindIndex != -1) {
					delSelectedRow.push(v_FindIndex);
					v_FindIndexSave = v_FindIndex;
				}
			}
		}

		//위 구문을 통해 SelectRow된 행(미결이 아니면서 에러내용이 없는 접수번호를 가진 row)를 삭제한다
		dlt_JeopsuhamMokrok.clearFilter();
		dlt_JeopsuhamMokrok.setBroadcast(true);
		dlt_JeopsuhamMokrok.removeRows(delSelectedRow);

		st_totalCnt2.setValue("총 <strong>" + dlt_JeopsuhamMokrok.getRowCount() + "</strong>건");

	} else if (dma_IlgwalCheck.get("MENU_FG") == "3") {

        //결재중
		if(typeof(dlt_DeleteJeopsuNo) == 'undefined') {
			com.create('dlt_DeleteJeopsuNo', dlt_GyeoljaejungMokrok.getAllArray().columnInfo);
		} else {
			$p.data.remove('dlt_DeleteJeopsuNo');
			com.create('dlt_DeleteJeopsuNo', dlt_GyeoljaejungMokrok.getAllArray().columnInfo);
		}

		dlt_GyeoljaejungMokrok.setBroadcast(false);		//Dataset에 Filter를 적용시켰을 때 그리드에 반영시키지 않기 위하여
		com.dataListFilter("dlt_GyeoljaejungMokrok", "ERROR_NAEYONG=='' && GYEOLJAE_FG!='0'");
		scwin.fv_GyeoljaejungAftGyeoljaeCnt = dlt_GyeoljaejungMokrok.getRowCount();
		dlt_DeleteJeopsuNo.setJSON(dlt_GyeoljaejungMokrok.getAllFilteredJSON());

		var v_FindIndexSave = "";	//v_FindIndex가 -1로 세팅될 경우 유효한 예전값으로 원복시키기 위한 값
