/*******************************************************************************
* FUNCTION 명 : scwin.fn_SetErrorMessage
* FUNCTION 기능설명 : out으로 나온 dlt_MokrokInfo의 ERROR_NAEYONG를 그리드의 에러내용에 바인딩시키기 / 메뉴구분에 따라 목록건수, 선택건수, 처리건수 세팅
*******************************************************************************/
scwin.fn_SetErrorMessage = function() {
	var v_geonsu = new Array();

	if (dma_IlgwalCheck.get("MENU_FG") == "1") {

        //결재함
		for (var inx=0; inx<dlt_MokrokInfo.getRowCount(); inx++) {
			for (var idx=0; idx<dlt_GyeoljaehamMokrok.getRowCount(); idx++) {
				if (dlt_MokrokInfo.getCellData(inx, "GIJUN_JEOPSU_NO") == dlt_GyeoljaehamMokrok.getCellData(idx, "GIJUN_JEOPSU_NO") &&
					dlt_MokrokInfo.getCellData(inx, "BOHEOM_FG") == dlt_GyeoljaehamMokrok.getCellData(idx, "BOHEOM_FG")) {
					dlt_GyeoljaehamMokrok.setCellData(idx, "ERROR_NAEYONG", dlt_MokrokInfo.getCellData(inx, "ERROR_NAEYONG"));
				}
			}
		}

		com.dataListFilter("dlt_GyeoljaehamMokrok", "YN=='N'");
		v_geonsu[0] = dlt_GyeoljaehamMokrok.getRowCount(); 	//목록건수 세팅

		com.dataListFilter("dlt_GyeoljaehamMokrok", "YN=='N' && GYEOLJAE_FG!='0'");	//미결을 제외한 Dataset
		v_geonsu[1] = dlt_GyeoljaehamMokrok.getRowCount(); 	//선택건수 세팅

		dlt_GyeoljaehamMokrok.clearFilter();
		v_geonsu[2] = dma_ResultInfo.get("CHEORI_CNT"); 	//처리건수 세팅

		return v_geonsu;

	} else if (dma_IlgwalCheck.get("MENU_FG") == "2") {

        //접수함
		for (var inx=0; inx<dlt_MokrokInfo.getRowCount(); inx++) {
			for (var idx=0; idx<dlt_JeopsuhamMokrok.getRowCount(); idx++) {
				if (dlt_MokrokInfo.getCellData(inx, "GIJUN_JEOPSU_NO") == dlt_JeopsuhamMokrok.getCellData(idx, "GIJUN_JEOPSU_NO")
						&& dlt_MokrokInfo.getCellData(inx, "BOHEOM_FG") == dlt_JeopsuhamMokrok.getCellData(idx, "BOHEOM_FG")) {
					dlt_JeopsuhamMokrok.setCellData(idx, "ERROR_NAEYONG", dlt_MokrokInfo.getCellData(inx, "ERROR_NAEYONG"));
				}
			}
		}

		com.dataListFilter("dlt_JeopsuhamMokrok", "YN=='N'");
		v_geonsu[0] = dlt_JeopsuhamMokrok.getRowCount(); 	//목록건수 세팅

		com.dataListFilter("dlt_JeopsuhamMokrok", "YN=='N' && GYEOLJAE_FG!='0'");	//미결을 제외한 Dataset
		v_geonsu[1] = dlt_JeopsuhamMokrok.getRowCount(); 	//선택건수 세팅

		dlt_JeopsuhamMokrok.clearFilter();
		v_geonsu[2] = dma_ResultInfo.get("CHEORI_CNT"); 	//처리건수 세팅

        return v_geonsu;

	} else if (dma_IlgwalCheck.get("MENU_FG") == "3") {

        //결재중
		for (var inx=0; inx<dlt_MokrokInfo.getRowCount(); inx++) {
			for (var idx=0; idx<dlt_GyeoljaejungMokrok.getRowCount(); idx++) {
				if (dlt_MokrokInfo.getCellData(inx, "GIJUN_JEOPSU_NO") == dlt_GyeoljaejungMokrok.getCellData(idx, "GIJUN_JEOPSU_NO")
						&& dlt_MokrokInfo.getCellData(inx, "BOHEOM_FG") == dlt_GyeoljaejungMokrok.getCellData(idx, "BOHEOM_FG")) {
					dlt_GyeoljaejungMokrok.setCellData(idx, "ERROR_NAEYONG", dlt_MokrokInfo.getCellData(inx, "ERROR_NAEYONG"));
				}
			}
		}

		dlt_GyeoljaejungMokrok.setBroadcast(false);		//Dataset에 Filter를 적용시켰을 때 그리드에 반영시키지 않기 위하여
		com.dataListFilter("dlt_GyeoljaejungMokrok", "YN=='N'");	//미결을 제외한 Dataset
		v_geonsu[0] = dlt_GyeoljaejungMokrok.getRowCount(); 	//목록건수 세팅

		com.dataListFilter("dlt_GyeoljaejungMokrok", "YN=='N' && GYEOLJAE_FG!='0'");	//미결을 제외한 Dataset
		v_geonsu[1] = dlt_GyeoljaejungMokrok.getRowCount(); 	//선택건수 세팅

		dlt_GyeoljaejungMokrok.clearFilter();
		dlt_GyeoljaejungMokrok.setBroadcast(true);

		v_geonsu[2] = dma_ResultInfo.get("CHEORI_CNT"); 	//처리건수 세팅

		return v_geonsu;

	} else if (dma_IlgwalCheck.get("MENU_FG") == "4") {

        //반려함
		v_geonsu[0] = dlt_BanryeohamMokrok.getRowCount(); 	//목록건수 세팅

		com.dataListFilter("dlt_BanryeohamMokrok", "CHECK=='1'");	//"해제"체크박스 선택된 건수 Dataset
		v_geonsu[1] = dlt_BanryeohamMokrok.getRowCount(); 	//선택건수 세팅
		dlt_BanryeohamMokrok.clearFilter();

		v_geonsu[2] = dma_ResultInfo.get("CHEORI_CNT"); 	//처리건수 세팅

		return v_geonsu;

	} else if (dma_IlgwalCheck.get("MENU_FG") == "5") {

        //보류함
		v_geonsu[0] = dlt_BoryuhamMokrok.getRowCount(); 	//목록건수 세팅

		com.dataListFilter("dlt_BoryuhamMokrok", "CHECK=='1'");	//"해제"체크박스 선택된 건수 Dataset
		v_geonsu[1] = dlt_BoryuhamMokrok.getRowCount(); 	//선택건수 세팅
		dlt_BoryuhamMokrok.clearFilter();

		v_geonsu[2] = dma_ResultInfo.get("CHEORI_CNT"); 	//처리건수 세팅

		return v_geonsu;
	}

	return;
};



