/*******************************************************************************
* FUNCTION 명 : scwin.dma_GyeoljaehamJohoeJogeon_onmodelchange
* FUNCTION 기능설명 : dma_GyeoljaehamJohoeJogeon 데이터 변경 시 이벤트
*******************************************************************************/
scwin.dma_GyeoljaehamJohoeJogeon_onmodelchange = async function(info) {

	//민원구분선택
	if (info.key == "MINWON_FG") {
		scwin.fn_SelectMinwonFg(info.newValue);
		edt_GyeoljaehamJohoeJogeon_minwonDoc.setValue("");
		edt_GyeoljaehamJohoeJogeon_minwonDoc2.setValue("");
	}

	//번호구분변경에 따른 mask 세팅
	if (info.key == "NO_FG") {
		scwin.fn_SelectNoFg(info.newValue);
	}

	//대결할자 체크
	if (info.key == "DAMDANGJA_FG") {
		if (info.newValue == "") {
            //전체
			edt_GyeoljaehamJohoeJogeon_userFg1.setDisabled(true);
			edt_GyeoljaehamJohoeJogeon_userFg1.setReadOnly(false);
			edt_GyeoljaehamJohoeJogeon_userFg3.setReadOnly(false);
			btn_GyeoljaehamJohoeJogeon_SelectUserPup.setDisabled(true);
			btn_GyeoljaehamJohoeJogeon_SelectGyeoljaejaPup.setDisabled(true);
			edt_GyeoljaehamJohoeJogeon_userFg1.setMandatory(false);

		} else if (info.newValue == "2") {
            //대결자:2
			await scwin.fn_CheckUserFg();
			edt_GyeoljaehamJohoeJogeon_userFg1.setDisabled(true);
			btn_GyeoljaehamJohoeJogeon_SelectUserPup.setDisabled(true);
			btn_GyeoljaehamJohoeJogeon_SelectGyeoljaejaPup.setDisabled(true);
			edt_GyeoljaehamJohoeJogeon_userFg1.setMandatory(true);

		} else {
            //담당자:1
			edt_GyeoljaehamJohoeJogeon_userFg1.setDisabled(false);
			edt_GyeoljaehamJohoeJogeon_userFg1.setReadOnly(false);
			edt_GyeoljaehamJohoeJogeon_userFg3.setDisabled(true);
			btn_GyeoljaehamJohoeJogeon_SelectUserPup.setDisabled(false);
			btn_GyeoljaehamJohoeJogeon_SelectGyeoljaejaPup.setDisabled(false);
			edt_GyeoljaehamJohoeJogeon_userFg1.setMandatory(true);
			edt_GyeoljaehamJohoeJogeon_userFg1.focus();
		}

		edt_GyeoljaehamJohoeJogeon_userFg1.setValue("");
		edt_GyeoljaehamJohoeJogeon_userFg3.setValue("");
	}

	//관리지사변경시 (0000 선택되지 못하게 체크)
	if (info.key == "GWANRI_JISA_CD") {
		if (info.newValue == "0000") {
			await com.gfn_MsgAlert("MLCA058");
			edt_GyeoljaehamJohoeJogeon_gwanriJisa.setValue(info.oldValue);
		}
	}

	//관리지사명변경시 (0000 선택되지 못하게 체크)
	if (info.key == "GWANRI_JISA_NM") {
		if (info.newValue == "전체") {
			edt_GyeoljaehamJohoeJogeon_gwanriJisa2.setValue(info.oldValue);
		}
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_SelectMinwonFg
* FUNCTION 기능설명 : 민원구분선택
*******************************************************************************/
scwin.fn_SelectMinwonFg = function(varNewValue) {

	if (varNewValue == "2") {
        //보상
		div0_title.visible(true);
		div0.visible(true);
		div1_title.visible(true);
		div1.visible(true);
		com.dataListFilter("dlt_NoFg", "GT_CD != '3'", false);
		cob_GyeoljaehamJohoeJogeon_noFg.setValue("");

	} else if (varNewValue == "4") {
        //법원문서
		div0_title.visible(false);
		div0.visible(false);
		edt_GyeoljaehamJohoeJogeon_gwanriNo.setValue("");
		edt_GyeoljaehamJohoeJogeon_gwanriNo2.setValue("");
		div1_title.visible(true);
		div1.visible(true);
		com.dataListFilter("dlt_NoFg", "GT_CD == '3'", false);
		cob_GyeoljaehamJohoeJogeon_noFg.setValue(3);

	} else if (varNewValue == "8") {
		div0_title.visible(false);
		div0.visible(false);
		div1_title.visible(false);
		div1.visible(false);

	}

	edt_GyeoljaehamJohoeJogeon_noFg1.setValue("");
	edt_GyeoljaehamJohoeJogeon_noFg2.setValue("");
}



/*******************************************************************************
* FUNCTION 명 : scwin.fn_SelectNoFg
* FUNCTION 기능설명 : 번호구분변경에 따른 mask 세팅
*******************************************************************************/
scwin.fn_SelectNoFg = function (varNewValue) {

	if (varNewValue == "1") {
		//재해자주민번호
		edt_GyeoljaehamJohoeJogeon_noFg1.setDisabled(false);
		edt_GyeoljaehamJohoeJogeon_noFg1.setDisplayFormat("######-#######");
		edt_GyeoljaehamJohoeJogeon_noFg1.setPlaceholder("______-_______");
		edt_GyeoljaehamJohoeJogeon_noFg1.setMaxLength(13);

		edt_GyeoljaehamJohoeJogeon_noFg2.setDisabled(true);
		edt_GyeoljaehamJohoeJogeon_noFg2.setDisplayFormat("######-#######");
		edt_GyeoljaehamJohoeJogeon_noFg2.setPlaceholder("______-_______");
		edt_GyeoljaehamJohoeJogeon_noFg2.setMaxLength(13);

	} else if(varNewValue == "2") {
		//의료기관번호
		edt_GyeoljaehamJohoeJogeon_noFg1.setDisabled(false);
		edt_GyeoljaehamJohoeJogeon_noFg1.setDisplayFormat("#-#######");
		edt_GyeoljaehamJohoeJogeon_noFg1.setPlaceholder("_-_______");
		edt_GyeoljaehamJohoeJogeon_noFg1.setMaxLength(8);

		edt_GyeoljaehamJohoeJogeon_noFg2.setDisabled(false);
		edt_GyeoljaehamJohoeJogeon_noFg2.setDisplayFormat("#-#######");
		edt_GyeoljaehamJohoeJogeon_noFg2.setPlaceholder("_-_______");
		edt_GyeoljaehamJohoeJogeon_noFg2.setMaxLength(8);

	} else if(varNewValue == "3") {
		//사건번호
		edt_GyeoljaehamJohoeJogeon_noFg1.setDisabled(false);
		edt_GyeoljaehamJohoeJogeon_noFg1.setDisplayFormat("");
		edt_GyeoljaehamJohoeJogeon_noFg1.setPlaceholder("");
		edt_GyeoljaehamJohoeJogeon_noFg1.setMaxLength(15);

		edt_GyeoljaehamJohoeJogeon_noFg2.setDisabled(false);
		edt_GyeoljaehamJohoeJogeon_noFg2.setDisplayFormat("");
		edt_GyeoljaehamJohoeJogeon_noFg2.setPlaceholder("");
		edt_GyeoljaehamJohoeJogeon_noFg2.setMaxLength(15);

	} else if(com.gfn_IsNull(varNewValue)) {
		//-선택-
		edt_GyeoljaehamJohoeJogeon_noFg1.setDisabled(true);
		edt_GyeoljaehamJohoeJogeon_noFg1.setDisplayFormat("");
		edt_GyeoljaehamJohoeJogeon_noFg1.setPlaceholder("");

		edt_GyeoljaehamJohoeJogeon_noFg2.setDisabled(true);
		edt_GyeoljaehamJohoeJogeon_noFg2.setDisplayFormat("");
		edt_GyeoljaehamJohoeJogeon_noFg2.setPlaceholder("");
	}

	edt_GyeoljaehamJohoeJogeon_noFg1.setValue("");
	edt_GyeoljaehamJohoeJogeon_noFg2.setValue("");

}



/*******************************************************************************
* FUNCTION 명 : scwin.fn_CheckUserFg
* FUNCTION 기능설명 : 대결할자 체크
*******************************************************************************/
scwin.fn_CheckUserFg = async function() {
	dma_UserInfo.set("USER_ID", com.gfn_SsGetId());
	dma_UserInfo.set("GYEOLJAE_EOPMU_CD", "X");

	var srvId		 = "RetrieveDaegyeoljaGeuntaeCmd";
	var strURL		 = "/cm/cm02/0101/CM0201100M_E005.do";
	var strinDsList	 = "['dma_UserInfo']";
	var stroutDsList = "['dlt_GeuntaeInfo']";
	var strArgument	 = "";
	var strCallback  = scwin.fn_CallBack;

    await com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, false, true, true);
}



/*******************************************************************************
* FUNCTION 명 : scwin.chk_GyeoljaehamJohoeJogeon_jeopsuNoYn_onchange
* FUNCTION 기능설명 : 기준접수번호 체크박스 이벤트
*******************************************************************************/
scwin.chk_GyeoljaehamJohoeJogeon_jeopsuNoYn_onchange = function(info) {

	if (mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.getValue().length != 15) {

		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.setValue(scwin.fv_GijunJeopsuNo);

	} else if (mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.getValue().length != 15
				&& mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.getValue().length != 15) {

		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.setValue(scwin.fv_GijunJeopsuNo);

	} else if (mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.getValue().length == 15
				&& mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.getValue().length != 15) {

		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.setValue(mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.getValue());

	}

	if (chk_GyeoljaehamJohoeJogeon_jeopsuNoYn.getValue() == "Y") {
        //"기준접수번호로조회"체크시 (처리일자 - 필수입력아님, 비활성화 / 접수번호 - 필수입력)
		edt_GyeoljaehamJohoeJogeon_cheoriDt.setValue("");
		edt_GyeoljaehamJohoeJogeon_cheoriDt1.setValue("");
		edt_GyeoljaehamJohoeJogeon_cheoriDt.setDisabled(true);
		edt_GyeoljaehamJohoeJogeon_cheoriDt1.setDisabled(true);
		st_GyeoljaehamJohoeJogeon_gijunJeopsuNo.setValue("기준접수번호");

		if (!st_GyeoljaehamJohoeJogeon_gijunJeopsuNo.hasClass("req")) {
			st_GyeoljaehamJohoeJogeon_gijunJeopsuNo.addClass("req");
		}
		if (st_GyeoljaehamJohoeJogeon_cheoriDt.hasClass("req")) {
			st_GyeoljaehamJohoeJogeon_cheoriDt.removeClass("req");
		}

		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.setMandatory(true);
		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.setMandatory(true);
		edt_GyeoljaehamJohoeJogeon_cheoriDt.setMandatory(false);
		edt_GyeoljaehamJohoeJogeon_cheoriDt1.setMandatory(false);
		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.setDisabled(true);
		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.setValue("");

	} else {
        //"기준접수번호로조회"체크해제시 (처리일자 - 필수입력, 활성화 / 기준접수번호 - 필수입력아님)
		edt_GyeoljaehamJohoeJogeon_cheoriDt1.setValue(com.substr(com.gfn_GetDate(), 0, 8));
		edt_GyeoljaehamJohoeJogeon_cheoriDt.setValue(com.addDate(com.substr(com.gfn_GetDate(), 0, 8), -20));
		edt_GyeoljaehamJohoeJogeon_cheoriDt.setDisabled(false);
		edt_GyeoljaehamJohoeJogeon_cheoriDt1.setDisabled(false);
		st_GyeoljaehamJohoeJogeon_gijunJeopsuNo.setValue("접수번호");

		if (st_GyeoljaehamJohoeJogeon_gijunJeopsuNo.hasClass("req")) {
			st_GyeoljaehamJohoeJogeon_gijunJeopsuNo.removeClass("req");
		}
		if(!st_GyeoljaehamJohoeJogeon_cheoriDt.hasClass("req"))
		{
			st_GyeoljaehamJohoeJogeon_cheoriDt.addClass("req")
		}

		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.setMandatory(false);
		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.setMandatory(false);
		edt_GyeoljaehamJohoeJogeon_cheoriDt.setMandatory(true);
		edt_GyeoljaehamJohoeJogeon_cheoriDt1.setMandatory(true);
		mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.setDisabled(false);
	}

	mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo.focus();
};



