*******************************************************************************/
scwin.fn_GianJakseong = function(v_YgId) {
	var URL_PARAM = "";
	URL_PARAM = "userid=" + com.gfn_SsGetId();
	URL_PARAM = URL_PARAM + "&dataurl=" + v_YgId;
