	var IE_HEADERS = "Content-Type: application/x-www-form-urlencoded\n";
	AxMSIE0.Navigate2("http://"+gv_gwYGUrl+":"+gv_gwYGPort+"/acubecn/related/CN_RelatedGwDocument.jsp", "", "_blank" , encodeURI(URL_PARAM), IE_HEADERS);
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_HochulGwYgMokrok
* FUNCTION 기능설명 : WN연계 이미지 클릭시 그룹웨어연계목록 조회 팝업 호출
*******************************************************************************/
scwin.fn_HochulGwYgMokrok = function(v_JeopsuNo, v_MinwonFg, v_GyeoljaeStatusCd) {
	if (!com.gfn_IsNull(v_JeopsuNo) && !com.gfn_IsNull(v_MinwonFg)) {
		var param =   "fv_JEOPSU_NO=" + com.quote(com.trim(v_JeopsuNo))
		           + " fv_MINWON_FG=" + com.quote(com.trim(v_MinwonFg))
		           + " fv_GYEOLJAE_STATUS_CD=" + com.quote(com.trim(v_GyeoljaeStatusCd));
		com.gfn_Dialog("/ui/biz/q/qb01/QB0101_P05.xml",param,720,440,"그룹웨어 연계목록 조회");

	} else {
		return;
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.grd_GyeoljaehamMokrok_oncellclick
* FUNCTION 기능설명 : 결재함 체크박스 라디오버튼 기능 / WN연계 이미지 클릭시 기안문작성 웹페이지 호출
*******************************************************************************/
scwin.grd_GyeoljaehamMokrok_oncellclick = async function(row,col,colId) {

	var v_FindIndex = 0;
	var tmpRow = row;

	var v_JeopsuNo 			= dlt_GyeoljaehamMokrok.getCellData(row, "JEOPSU_NO");
	var v_MinwonFg 			= dlt_GyeoljaehamMokrok.getCellData(row, "MINWON_FG");
	var v_GyeoljaeStatusCd	= dlt_GyeoljaehamMokrok.getCellData(row, "GYEOLJAE_STATUS_CD");
	var v_GwYn 				= dlt_GyeoljaehamMokrok.getCellData(row, "GW_YN");

	if (col == 5) {
        //승인
		if (!scwin.fn_GetJehanCntInfo("1")) {
			await com.gfn_Alert(scwin.fv_JehanMsg);
		} else {
			while (v_FindIndex != -1) {
				if (dlt_GyeoljaehamMokrok.getCellData(row, "GIJUN_JEOPSU_NO") == dlt_GyeoljaehamMokrok.getCellData(tmpRow, "GIJUN_JEOPSU_NO")) {
                    dlt_GyeoljaehamMokrok.setCellData(tmpRow, "SEUNGIN", "1");
                    dlt_GyeoljaehamMokrok.setCellData(tmpRow, "GYEOLJAE_FG", "1");
                    dlt_GyeoljaehamMokrok.setCellData(tmpRow, "BORYU", "0");
                    dlt_GyeoljaehamMokrok.setCellData(tmpRow, "MIGYEOL", "0");
                    dlt_GyeoljaehamMokrok.setCellData(tmpRow, "BANRYO", "0");
					tmpRow = tmpRow + 1;
					v_FindIndex = 0;

				} else {
					v_FindIndex = -1;
				}
			}
		}

	} else if (col == 6) {
        //보류
		while (v_FindIndex != -1) {
			if (dlt_GyeoljaehamMokrok.getCellData(row, "GIJUN_JEOPSU_NO") == dlt_GyeoljaehamMokrok.getCellData(tmpRow, "GIJUN_JEOPSU_NO")) {
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "BORYU", "1");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "GYEOLJAE_FG", "3");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "SEUNGIN", "0");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "MIGYEOL", "0");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "BANRYO", "0");
				tmpRow = tmpRow + 1;
				v_FindIndex = 0;

			} else {
				v_FindIndex = -1;
			}
		}

	} else if (col == 11) {
        //반려
		while (v_FindIndex != -1) {
			if (dlt_GyeoljaehamMokrok.getCellData(row, "GIJUN_JEOPSU_NO") == dlt_GyeoljaehamMokrok.getCellData(tmpRow, "GIJUN_JEOPSU_NO")) {
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "BANRYO", "1");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "GYEOLJAE_FG", "2");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "BORYU", "0");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "MIGYEOL", "0");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "SEUNGIN", "0");
				tmpRow = tmpRow + 1;
				v_FindIndex = 0;

			} else {
				v_FindIndex = -1;
			}
		}

	} else if (col == 12) {
        //미결
		while (v_FindIndex != -1) {
			if (dlt_GyeoljaehamMokrok.getCellData(row, "GIJUN_JEOPSU_NO") == dlt_GyeoljaehamMokrok.getCellData(tmpRow, "GIJUN_JEOPSU_NO")) {
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "MIGYEOL", "1");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "GYEOLJAE_FG", "0");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "BORYU", "0");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "SEUNGIN", "0");
                dlt_GyeoljaehamMokrok.setCellData(tmpRow, "BANRYO", "0");
				tmpRow = tmpRow + 1;
				v_FindIndex = 0;

			} else {
				v_FindIndex = -1;
			}
		}
	}

	if (col == 0) {
		if (v_GwYn == "Y" && !com.gfn_IsNull(v_JeopsuNo) && !com.gfn_IsNull(v_MinwonFg)) {
			scwin.fn_HochulGwYgMokrok(v_JeopsuNo, v_MinwonFg, v_GyeoljaeStatusCd);
		}

	} else if (col == 14) {
        //지시사항
		if (dlt_GyeoljaehamMokrok.getCellData(row, "MIGYEOL") == 1) {
			await com.gfn_MsgAlert("MQBA011");	//지시사항은 '승인', '반려', '보류' 일 때 입력할 수 있습니다.
		} else if (dlt_GyeoljaehamMokrok.getCellData(row, "SEUNGIN") == 1
					&& dlt_GyeoljaehamMokrok.getCellData(row, "LAST_GYEOLJAEJA_ID") != com.gfn_SsGetId()) {
			await com.gfn_MsgAlert("MQBA012");	//최종결재자가 아니면 '승인'의 지시사항은 입력할 수 없습니다.
		} else {
			scwin.fn_Jisisahang(row);
		}
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_Jisisahang
* FUNCTION 기능설명 : 결재함탭 내의 지시시항
*******************************************************************************/
scwin.fn_Jisisahang = async function(nRow) {
	var v_Param = "fv_JeopsuNo=" + com.quote(dlt_GyeoljaehamMokrok.getCellData(nRow, "JEOPSU_NO"));
	v_Param += " fv_MinwonDocNM=" + com.quote(dlt_GyeoljaehamMokrok.getCellData(nRow, "MINWON_DOC_NM"));
	v_Param += " fv_BefJisisahang=" + com.quote(dlt_GyeoljaehamMokrok.getCellData(nRow, "JISI_SAHANG"));
	var v_Jisisahang = new Array();
	v_Jisisahang = await com.gfn_Dialog("/ui/sia/biz/cm/cm02/0101/CM0201112P.xml", v_Param, 560, 510, "지시사항");

	//지시사항 내용이 있을 시에만 이전지시사항 내용을 덮어씌운다.
	if (!com.gfn_IsNull(v_Jisisahang[0])) {
		dlt_GyeoljaehamMokrok.setBroadcast(false);
		dlt_GyeoljaehamMokrok.setCellData(nRow, "JISI_SAHANG", v_Jisisahang[0]);
		dlt_GyeoljaehamMokrok.setBroadcast(true);
	}
};



