/*******************************************************************************
* FUNCTION 명 : scwin.grd_GyeoljaehamMokrok_oncelldblclick
* FUNCTION 기능설명 : 결재함목록선택(그리드 Cell 더블클릭 시 이벤트)
*******************************************************************************/
scwin.grd_GyeoljaehamMokrok_oncelldblclick = async function(row,col,colId) {

	//결재구분 체크박스 더블클릭을 제외하고 (체크박스 선택/해제를 위해서 더블클릭이 유도되었을 경우를 제외하기 위해)
	if (col != 0 && col != 5 && col != 6 && col != 11 && col != 12) {
		var strParam = "";
		var v_ProgramId = "";
