/*******************************************************************************
* FUNCTION 명 : scwin.fn_JeopsuStatusCdChk
* FUNCTION 기능설명 : 접수상태코드 체크
*******************************************************************************/
scwin.fn_JeopsuStatusCdChk = async function(jeopsuStCd) {

	/* 접수상태코드 5:반려, 7:이송, 9:기타, E:이중접수, H:2차 불승인*/
	if (jeopsuStCd == "5" || jeopsuStCd == "7" || jeopsuStCd == "9" ||
		jeopsuStCd == "E" || jeopsuStCd == "H") {

		await com.gfn_MsgAlert("MQAA055"); /* 기타처리된 접수내역은 연계화면이 없습니다.*/
		return false;
	}

	return true;
};



