/*******************************************************************************
* FUNCTION 명 : scwin.mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1_onkeydown
* FUNCTION 기능설명 : 조회 전 조회조건 입력컴포넌트 엔터키 입력시 조회 가능
*******************************************************************************/
scwin.mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1_onkeydown = function(e) {
	// Shift, Control, Alt 키가 눌려져 있지 않은 경우만 단축키 실행.
	if (!e.shiftKey && !e.ctrlKey && !e.altKey) {
		if (e.keyCode == "13") {
			scwin.btn_Johoe_onclick();
		}
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.jeopsuhamFormatter
* FUNCTION 기능설명 : 접수번호 Mask 처리(YN== "Y"인 경우에만 접수번호 들여쓰기)
*******************************************************************************/
scwin.jeopsuhamFormatter = function (value, formattedValue, rowIdx, colIdx) {

	//WN연계 컬럼 아이콘
	if (dlt_JeopsuhamMokrok.getCellData(rowIdx, "GW_YN") == 'Y') {
		grd_JeopsuhamMokrok.setCellInputType(rowIdx, "GW_YN", scwin.gwYnImageInfo);
	}

	//첨부파일 컬럼 아이콘
	if (dlt_JeopsuhamMokrok.getCellData(rowIdx, "CHEOMBUFILE_YN") == 'Y') {
		grd_JeopsuhamMokrok.setCellInputType(rowIdx, "CHEOMBUFILE_YN", scwin.cheombufileYnImageInfo);
	}

	//접수번호, 관리번호, 민원서류명 컬럼
	if(dlt_JeopsuhamMokrok.getCellData(rowIdx, "MINWON_DOC_CD") == "8028" || dlt_JeopsuhamMokrok.getCellData(rowIdx, "MINWON_DOC_CD") == "8080") {
		grd_JeopsuhamMokrok.setCellColor(rowIdx, "JEOPSU_NO", "red");
		grd_JeopsuhamMokrok.setCellColor(rowIdx, "GWANRI_NO", "red");
		grd_JeopsuhamMokrok.setCellColor(rowIdx, "MINWON_DOC_NM", "red");
	}

	//에러내용 컬럼
	grd_JeopsuhamMokrok.setCellColor(rowIdx, "ERROR_NAEYONG", "red");

	//결재 컬럼
    if (dlt_JeopsuhamMokrok.getCellData(rowIdx, "YN") == 'Y') {
		grd_JeopsuhamMokrok.setCellInputType(rowIdx, "GYEOLJAE", null);
		grd_JeopsuhamMokrok.setCellInputType(rowIdx, "BORYU", null);
		grd_JeopsuhamMokrok.setCellInputType(rowIdx, "MIGYEOL", null);
	} else {
		grd_JeopsuhamMokrok.setCellInputType(rowIdx, "GYEOLJAE", {inputType: "checkbox", options: {trueValue: 1, falseValue: 0, checkboxLabel: "결재"}});
		grd_JeopsuhamMokrok.setCellInputType(rowIdx, "BORYU", {inputType: "checkbox", options: {trueValue: 1, falseValue: 0, checkboxLabel: "보류"}});
		grd_JeopsuhamMokrok.setCellInputType(rowIdx, "MIGYEOL", {inputType: "checkbox", options: {trueValue: 1, falseValue: 0, checkboxLabel: "미결"}});
	}

	//결재요약정보 컬럼
	if(com.left(dlt_JeopsuhamMokrok.getCellData(rowIdx, "YOYAK_INFO"), 4) == "diff") {

		grd_JeopsuhamMokrok.setCellColor(rowIdx, "YOYAK_INFO", "red");

		var value = dlt_JeopsuhamMokrok.getCellData(rowIdx, "YOYAK_INFO");
		if (com.left(value, 4) == "diff") {
			dlt_JeopsuhamMokrok.setCellData(rowIdx, "YOYAK_INFO", com.replace(value, "diff", ""));
		} else if (com.left(value, 5) == "diff ") {
			dlt_JeopsuhamMokrok.setCellData(rowIdx, "YOYAK_INFO", com.replace(value, "diff ", ""));
		}
	}

	//접수번호 컬럼
    if (dlt_JeopsuhamMokrok.getCellData(rowIdx, "YN") == 'Y') {
		grd_JeopsuhamMokrok.setCellClass(rowIdx, "JEOPSU_NO", "gridTagInTab");
        retVal = " ― " + formattedValue;
    } else {
        retVal = " ■ " + formattedValue;
    }

    return retVal;
};



/*******************************************************************************
* FUNCTION 명 : scwin.gyeoljaehamFormatter
* FUNCTION 기능설명 : 접수번호 Mask 처리(YN== "Y"인 경우에만 접수번호 들여쓰기)
*******************************************************************************/
scwin.gyeoljaehamFormatter = function (value, formattedValue, rowIdx, colIdx) {

	//WN연계 컬럼 아이콘
	if (dlt_GyeoljaehamMokrok.getCellData(rowIdx, "GW_YN") == 'Y') {
		grd_GyeoljaehamMokrok.setCellInputType(rowIdx, "GW_YN", scwin.gwYnImageInfo);
	}

	//지시사항 컬럼
	if (dlt_GyeoljaehamMokrok.getCellData(rowIdx, "YN") == 'N') {
		grd_GyeoljaehamMokrok.setCellInputType(rowIdx, "JISI_SAHANG", {inputType: "button", options: {class: "btn cr3"}, itemSet: {value: "지시사항"}});
	}

	//첨부파일 컬럼 아이콘
	if (dlt_GyeoljaehamMokrok.getCellData(rowIdx, "CHEOMBUFILE_YN") == 'Y') {
		grd_GyeoljaehamMokrok.setCellInputType(rowIdx, "CHEOMBUFILE_YN", scwin.cheombufileYnImageInfo);
	}

	//접수번호, 관리번호, 민원서류명 컬럼
	if(dlt_GyeoljaehamMokrok.getCellData(rowIdx, "MINWON_DOC_CD") == "8028" || dlt_GyeoljaehamMokrok.getCellData(rowIdx, "MINWON_DOC_CD") == "8080") {
		grd_GyeoljaehamMokrok.setCellColor(rowIdx, "JEOPSU_NO", "red");
		grd_GyeoljaehamMokrok.setCellColor(rowIdx, "GWANRI_NO", "red");
		grd_GyeoljaehamMokrok.setCellColor(rowIdx, "MINWON_DOC_NM", "red");
	}

	//에러내용 컬럼
	grd_GyeoljaehamMokrok.setCellColor(rowIdx, "ERROR_NAEYONG", "red");

	//결재 컬럼
    if (dlt_GyeoljaehamMokrok.getCellData(rowIdx, "YN") == 'N') {
		grd_GyeoljaehamMokrok.setCellInputType(rowIdx, "SEUNGIN", {inputType: "checkbox", options: {trueValue: 1, falseValue: 0, checkboxLabel: "승인"}});
		grd_GyeoljaehamMokrok.setCellInputType(rowIdx, "BORYU", {inputType: "checkbox", options: {trueValue: 1, falseValue: 0, checkboxLabel: "보류"}});
		grd_GyeoljaehamMokrok.setCellInputType(rowIdx, "BANRYO", {inputType: "checkbox", options: {trueValue: 1, falseValue: 0, checkboxLabel: "반려"}});
		grd_GyeoljaehamMokrok.setCellInputType(rowIdx, "MIGYEOL", {inputType: "checkbox", options: {trueValue: 1, falseValue: 0, checkboxLabel: "미결"}});
	}

	//결재요약정보 컬럼
	if(dlt_GyeoljaehamMokrok.getCellData(rowIdx, "WIIM_JIKGEUP_CD") == "30" && dlt_GyeoljaehamMokrok.getCellData(rowIdx, "MINWON_DOC_CD") == "8618") {
		grd_GyeoljaehamMokrok.setCellColor(rowIdx, "YOYAK_INFO", "red");
	}

	if(com.left(dlt_GyeoljaehamMokrok.getCellData(rowIdx, "YOYAK_INFO"), 4) == "diff") {

		grd_GyeoljaehamMokrok.setCellColor(rowIdx, "YOYAK_INFO", "red");
		var value = dlt_GyeoljaehamMokrok.getCellData(rowIdx, "YOYAK_INFO");
		if (com.left(value, 4) == "diff") {
			dlt_GyeoljaehamMokrok.setCellData(rowIdx, "YOYAK_INFO", com.replace(value, "diff", ""));
		} else if (com.left(value, 5) == "diff ") {
			dlt_GyeoljaehamMokrok.setCellData(rowIdx, "YOYAK_INFO", com.replace(value, "diff ", ""));
		}
	}

	//접수번호 컬럼
    if (dlt_GyeoljaehamMokrok.getCellData(rowIdx, "YN") == 'Y') {
		grd_GyeoljaehamMokrok.setCellClass(rowIdx, "JEOPSU_NO", "gridTagInTab");
        retVal = " ― " + formattedValue;
    } else {
        retVal = " ■ " + formattedValue;
    }

    return retVal;
};



