scwin.emptyFormatter = function (value, formattedValue, rowIdx, colIdx) {
	return "";
};


scwin.wiimJikgeupCdFormatter = function (value, formattedValue, rowIdx, colIdx) {
	if(value == "00") {
		return "00 / 이사장";
	} else if(value == "05") {
		return "05 / 이사" ;
	} else if(value == "10") {
		return "10 / 지사장";
	} else if(value == "20") {
		return "20 / 부장";
	} else if(value == "30") {
		return "30 / 차장";
	} else if(value == "40") {
		return "40 / 담당";
	}
};


scwin.boheomFgFormatter = function (value, formattedValue, rowIdx, colIdx) {
	if (value == 1) {
		return "산재보험";
	} else if (value == 2) {
		return "임금채권";
	} else if (value == 3) {
		return "고용보험";
	} else if (value == 4) {
		return "산재 + 임채";
	} else if (value == 5) {
		return "산재 + 고용";
	} else if (value == 6) {
		return "임채 + 고용";
	} else if (value == 0) {
		return "산재 + 임채 + 고용";
	}
};


scwin.yoyakInfoFormatter = function (value) {
	if(com.left(value, 4) == "diff") {
		return com.replace(value, "diff", "");
	} else if(com.left(value, 5) == "diff ") {
		return com.replace(value, "diff ", "");
	} else {
		return value;
	}
};



scwin.fn_OnTimer = function(nEventID) {
    switch(nEventID) {
        case 1:
            //st_time.Value = fn_GetTestDate();
        break;
        case 2:
			console.log("#######################################      " + scwin.fv_BunhalCheoriInx + "       ###########################" );
            scwin.fn_GyeoljaeBunhalCheori(scwin.fv_BunhalCheoriInx++);
        break;
    }
};



scwin.fn_GyeoljaeBunhalCheori = async function(bunhalInx) {
	// KillTimer(2);
	$p.clearInterval("qb0101_Timer01");

	console.log("타이머 오프 ");
	console.log("########## fn_GyeoljaeBunhalCheori #############");
	console.log("bunhalInx = " + bunhalInx);
	var row = 0;
	var v_AddRow;

	var srvId		 = "HandleGyeoljaehamGyeoljaeCmd";
	var strURL		 = "/cm/cm02/0101/CM0201100M_E004.do";
	var strinDsList  = "['dma_IlgwalCheck', {'key':'dlt_MokrokInfoTmp','id':'dlt_MokrokInfoDiv'}]";
	var stroutDsList = "['dma_ResultInfo', 'dlt_MokrokInfo']";
	var strArgument	 = "";
	var strCallback  = scwin.fn_CallBack;

	var gRow = bunhalInx;

	scwin.fn_AddColumns();
	scwin.fv_StartInx = (gRow-1) * scwin.fv_LimitCnt;
	scwin.fv_EndInx   = gRow * scwin.fv_LimitCnt;

	if(gRow == scwin.fv_LoopCnt) {
		scwin.fv_EndInx = scwin.fv_PDsRowCnt;
	} else if(gRow > scwin.fv_LoopCnt) {
		scwin.fn_GyeoljaeBunhalCheoriAft();
		return;
	}

	for (row=scwin.fv_StartInx; row<scwin.fv_EndInx; row++) {
		dlt_MokrokInfoDiv.setRowJSON(scwin.fv_dsObj.getRowCount(), scwin.fv_pDsObj.getRowJSON(row));
	}

	await com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, false, true, true);
}



scwin.fn_GyeoljaeBunhalCheoriAft = async function() {

	console.log("########## fn_GyeoljaeBunhalCheoriAft #############");

	//결재처리 후 결재비밀번호 초기화
	edt_IlgwalCheck_gyeoljaePw.setValue("");
	// edt_IlgwalCheck_gyeoljaePw.SetFocus();
	// console.log("\n########################## => END TIME : " + com.gfn_GetDateTime() + " <= #########################\n");

	if (scwin.fv_failCnt == 0) {
		scwin.fn_DeleteRow();
	}
	scwin.fv_failCnt = 0;

	//결재처리 후 총건수 재출력을 위하여
	var v_param  = "fv_MokrokCnt=" 		+ scwin.fv_GyeoljaehamTotCnt;
		v_param += " fv_SeontaekCnt=" 	+ scwin.fv_PDsRowCnt;
		v_param += " fv_CheoriCnt=" 		+ scwin.fv_ResultCheoriCnt;
	await com.gfn_Dialog("/ui/sia/biz/cm/cm02/0101/CM0201111P.xml",v_param, 400, 260, "기준접수번호 처리 결과");
	scwin.fv_ResultTextCom.setValue("");
}


