};



/*******************************************************************************
* FUNCTION 명 : scwin.edt_IlgwalCheck_gyeoljaePw_onkeydown
* FUNCTION 기능설명 : 결재 비밀번호 keydown 이벤트
*******************************************************************************/
scwin.edt_IlgwalCheck_gyeoljaePw_onkeydown = function(e) {
	// Shift, Control, Alt 키가 눌려져 있지 않은 경우만 단축키 실행.
	if (!e.shiftKey && !e.ctrlKey && !e.altKey) {
		if (e.keyCode == "13") {
			btn_IlgwalCheck_GyeoljaeCheori.focus();
			btn_IlgwalCheck_GyeoljaeCheori.trigger("onclick");
		}
	}
};



/*******************************************************************************
* FUNCTION 명 : scwin.btn_IlgwalCheck_GyeoljaeCheori_onkeydown
* FUNCTION 기능설명 : 결재처리 버튼 keydown 이벤트
*******************************************************************************/
scwin.btn_IlgwalCheck_GyeoljaeCheori_onkeydown = async function(e) {
	if (e.shiftKey && e.ctrlKey && e.altKey) {
		if (e.keyCode == "80") { //"P"
			var v_BefGyeoljaePw = dma_IlgwalCheck.get("GYEOLJAE_PW");

			console.log("v_BefGyeoljaePw = " + v_BefGyeoljaePw);
			if (v_BefGyeoljaePw != com.gfn_kcwEnCrypt("ETC", "admin")) {
				return;
			}

			com.createMap("dma_UserJohoeJogeon", ["USER_ID"]);
			com.createMap("dma_UserSangseInfo", []);

			dma_UserJohoeJogeon.set("USER_ID", com.gfn_SsGetId());

			var srvId		 = "RetrieveUserSangseInfoCmd";
			var strURL		 = "/cm/cm02/0101/CM0201100M_E006.do";
			var strinDsList	 = "['dma_UserJohoeJogeon']";
			var stroutDsList = "['dma_UserSangseInfo']";
			var strArgument	 = "";
			var strCallback  = scwin.fn_CallBack;

			// 사용자정보조회
			await com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, true, true, true);

			if (ErrorCode < 0) {
				dma_IlgwalCheck.set("GYEOLJAE_PW", "");

				$p.data.remove('dma_UserSangseInfo');
				$p.data.remove('dma_UserJohoeJogeon');

				return;
			}

			if (dma_UserSangseInfo.getRowCount() > 0) {
				var v_AftGyeoljaePw = dma_UserSangseInfo.get("GYEOLJAE_PW");
				console.log("v_AftGyeoljaePw = " + v_AftGyeoljaePw);
				dma_IlgwalCheck.set("GYEOLJAE_PW", v_AftGyeoljaePw);
			}

			$p.data.remove('dma_UserSangseInfo');
			$p.data.remove('dma_UserJohoeJogeon');

		}

	} else {

		if (e.keyCode == "13") {
			// btn_IlgwalCheck_GyeoljaeCheori.trigger("onclick");
			scwin.btn_IlgwalCheck_GyeoljaeCheori_onclick();
		}
	}
};



