/*******************************************************************************
* FUNCTION 명 : scwin.fn_GetJehanCntInfo
* FUNCTION 기능설명 : 
*******************************************************************************/
scwin.fn_GetJehanCntInfo = function(v_TabFg) {

	if (com.gfn_IsNull(scwin.fv_JehanTmYn)) {
		scwin.fn_CheckIlgwalCheckJehan("N");
	}

	if (scwin.fv_JehanTmYn == "Y") {
		var v_OverJehanCntYn = false;

		if (v_TabFg == "1") {

			var caseCount = 0;
			for (var i=0; i<dlt_GyeoljaehamMokrok.getRowCount(); i++) {
				if (dlt_GyeoljaehamMokrok.getCellData(i, "YN") != "Y" && dlt_GyeoljaehamMokrok.getCellData(i, "GYEOLJAE_FG") == "1") {
					caseCount++;
				}
			}
			if (caseCount >= scwin.fv_JehanCnt) {
				v_OverJehanCntYn = true;
			}

		} else if (v_TabFg == "2") {

			var caseCount = 0;
			for (var i=0; i<dlt_JeopsuhamMokrok.getRowCount(); i++) {
				if (dlt_JeopsuhamMokrok.getCellData(i, "YN") != "Y" && dlt_JeopsuhamMokrok.getCellData(i, "GYEOLJAE_FG") == "1") {
					caseCount++;
				}
			}

			if (caseCount >= scwin.fv_JehanCnt) {
				v_OverJehanCntYn = true;
			}
		}

		if (v_OverJehanCntYn) {
			return false;
		}
	}

	return true;
};



/*******************************************************************************
* FUNCTION 명 : scwin.fn_GetUserEopmuMokrok
* FUNCTION 기능설명 : 
*******************************************************************************/
scwin.fn_GetUserEopmuMokrok = async function() {
	dma_GyeoljaeseonJogeon.setEmptyValue();
	dma_GyeoljaeseonJogeon.reform();
	dlt_GyeoljaeEopmuMokrok.removeAll();

	dma_GyeoljaeseonJogeon.set("USER_ID", com.gfn_SsGetId());

	var srvId		 = "RetrieveGyeoljaeEopmuMokrokCmd";	//retrieveGyeoljaeEopmuMokrokQBPC
	var strURL		 = "/cm/cm02/0101/CM0201100M_E008.do";
	var strinDsList	 = "['dma_GyeoljaeseonJogeon']";
	var stroutDsList = "['dlt_GyeoljaeEopmuMokrok']";
	var strArgument	 = "";
	var strCallback  = scwin.fn_CallBack;

	var v_rtn = await com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, true, true, true);

	if (v_rtn < 0) {
		return false;
	}

	cob_GyeoljaeEopmu.setSelectedIndex(0);
};



/*******************************************************************************
* FUNCTION 명 : scwin.btn_GyeoljaeSeonInfoJohoe_onclick
* FUNCTION 기능설명 : 결재선정보 버튼 click 이벤트
*******************************************************************************/
scwin.btn_GyeoljaeSeonInfoJohoe_onclick = function(e) {

	if (!com.gfn_IsNull(dma_GyeoljaeseonJogeon.get("USER_ID"))
			&& !com.gfn_IsNull(dma_GyeoljaeseonJogeon.get("GYEOLJAE_EOPMU_CD"))) {

		var param = "v_UserId=" + com.quote(dma_GyeoljaeseonJogeon.get("USER_ID"));
		param += " v_GyeoljaeEopmuCd=" + com.quote(dma_GyeoljaeseonJogeon.get("GYEOLJAE_EOPMU_CD"));
		com.gfn_Dialog("/ui/sia/biz/cm/cm02/0101/CM0201108P.xml",param, 650, 350, "결재선정보");

	} else {
		return;
	}
};




