/*******************************************************************************
* FUNCTION 명 : scwin.mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo_onkeydown
* FUNCTION 기능설명 : 접수번호 엔터키 클릭 이벤트
*******************************************************************************/
scwin.mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo_onkeydown = function(e) {
    // Shift, Control, Alt 키가 눌려져 있지 않은 경우만 단축키 실행.
	if (!e.shiftKey && !e.ctrlKey && !e.altKey) {
		if (e.keyCode == "13" || e.keyCode == "9") {
			if(chk_GyeoljaehamJohoeJogeon_jeopsuNoYn.getValue() == "Y") {
				edt_GyeoljaehamJohoeJogeon_gwanriNo.focus();
			} else {
				mae_GyeoljaehamJohoeJogeon_gijunJeopsuNo1.focus();
			}
		}
	}
};



